const MODULES=["Giới thiệu DBMS", "Giới thiệu SQL", "DDL – Ngôn ngữ định nghĩa dữ liệu", "Ràng buộc (Constraints)", "DML – Ngôn ngữ thao tác dữ liệu", "Hàm đơn hàng (Single Row)", "Hàm nhóm (Group Functions)", "Phép nối (SQL Joins)", "Truy vấn con (Sub Queries)", "Truy vấn con nâng cao", "Khung nhìn (Views)", "Toán tử tập hợp & Cột giả", "Chuẩn hóa (Normalization)"];
const DATA=[{"id":1,"m":1,"q":"Which of the following is not an advantage of the DBMS?","o":["User application data creation.","Data independence and efficient access.","Reduced application development time.","Data integrity and security."],"c":0,"qv":"Điều nào sau đây KHÔNG phải là ưu điểm của DBMS?","ov":["Tạo dữ liệu ứng dụng cho người dùng.","Tính độc lập dữ liệu và truy cập hiệu quả.","Giảm thời gian phát triển ứng dụng.","Toàn vẹn và bảo mật dữ liệu."],"ex":"Ba ưu điểm còn lại đều là lợi ích điển hình của DBMS; việc tạo dữ liệu ứng dụng do người dùng thực hiện, không phải ưu điểm của DBMS."},{"id":2,"m":1,"q":"Which Background process updates the online redo log files with the redo log buffer entries when a COMMIT occurs in the database?","o":["LGWR","DBWn","CKPT","CJQn"],"c":0,"qv":"Tiến trình nền (Background process) nào ghi các bản ghi từ redo log buffer vào các tệp online redo log khi xảy ra lệnh COMMIT?","ov":["LGWR","DBWn","CKPT","CJQn"],"ex":"LGWR (Log Writer) ghi nội dung redo log buffer vào online redo log files khi COMMIT. DBWn ghi dữ liệu, CKPT thực hiện checkpoint."},{"id":3,"m":1,"q":"Which files can be multiplexed?","o":["Data Files","Control Files","Parameter Files","Data Buffer Cache"],"c":0,"qv":"Những tệp nào có thể được nhân bản (multiplex)?","ov":["Tệp dữ liệu (Data Files)","Tệp điều khiển (Control Files)","Tệp tham số (Parameter Files)","Data Buffer Cache"],"ex":"Trong ngữ cảnh đề bài, đáp án đúng theo ngân hàng câu hỏi là Data Files."},{"id":4,"m":1,"q":"Which Statement about the Data files is not true?","o":["A data file Can belong to only one tablespace","At least one data file is required for each tablespace","Maintain the logs of the changes made to the database to enable recovery.","Data File contains the data in the database, including tables, indexes, temp segments etc"],"c":2,"qv":"Phát biểu nào về Data file là KHÔNG đúng?","ov":["Một data file chỉ có thể thuộc về một tablespace","Mỗi tablespace cần ít nhất một data file","Lưu nhật ký các thay đổi của CSDL để phục vụ khôi phục.","Data file chứa dữ liệu của CSDL, gồm bảng, chỉ mục, segment tạm, v.v."],"ex":"Việc lưu nhật ký thay đổi để khôi phục là vai trò của redo log files, không phải data file."},{"id":5,"m":1,"q":"Which Statement about the Oracle Initialization Parameter Files (init.ora) is not true?","o":["Enclose in quotation marks any parameter value that contains a special character","An initialization parameter file should contain only parameters and comments.","Several parameters can be specified on one line, separated by a space","Parameters must be specified in a predefined order."],"c":3,"qv":"Phát biểu nào về tệp tham số khởi tạo Oracle (init.ora) là KHÔNG đúng?","ov":["Đặt giá trị tham số có ký tự đặc biệt trong dấu nháy","Tệp chỉ nên chứa tham số và chú thích.","Có thể khai báo nhiều tham số trên một dòng, cách nhau bằng dấu cách","Các tham số phải được khai báo theo thứ tự định sẵn."],"ex":"Các tham số trong init.ora có thể khai báo theo thứ tự bất kỳ."},{"id":6,"m":1,"q":"What is not true about the Oracle Instance?","o":["Oracle Instance provides means to access Oracle database","Oracle Instance  is a collection of data that is treated as a unit, which stores and retrieves related information","Oracle Instance  can open and use one database at a time","Oracle Instance  consists of SGA and background processes"],"c":1,"qv":"Phát biểu nào về Oracle Instance là KHÔNG đúng?","ov":["Instance cung cấp phương tiện truy cập CSDL Oracle","Instance là tập hợp dữ liệu được xử lý như một đơn vị, dùng để lưu và truy xuất thông tin liên quan","Instance chỉ mở và sử dụng một CSDL tại một thời điểm","Instance gồm SGA và các tiến trình nền"],"ex":"Phát biểu B mô tả database, không phải instance. Instance = SGA + các tiến trình nền."},{"id":7,"m":1,"q":"Which of the following is not a part of System Global Area?","o":["Redo log Buffer","Data Buffer Cache","Parameter Files","Shared Pool"],"c":2,"qv":"Thành phần nào sau đây KHÔNG thuộc System Global Area (SGA)?","ov":["Redo log Buffer","Data Buffer Cache","Tệp tham số (Parameter Files)","Shared Pool"],"ex":"Parameter files là tệp trên đĩa, không nằm trong vùng nhớ SGA."},{"id":8,"m":1,"q":"Which of the following statements about the Data buffer cache is not true?","o":["Data buffer cache stores a collection of the most recently used SQL statements.","Data buffer cache stores the most recently used data","Data buffer cache read and write data to and from the data files","Size of each buffer in the Data buffer cache is equal to the size of an Oracle Block."],"c":0,"qv":"Phát biểu nào về Data buffer cache là KHÔNG đúng?","ov":["Data buffer cache lưu tập các câu lệnh SQL được dùng gần đây nhất.","Data buffer cache lưu dữ liệu được dùng gần đây nhất","Data buffer cache đọc/ghi dữ liệu từ/đến các data file","Kích thước mỗi buffer bằng kích thước một Oracle block"],"ex":"Các câu lệnh SQL gần đây được lưu trong Library Cache (Shared Pool), không phải Data buffer cache."},{"id":9,"m":1,"q":"Which of the following statements about the Redo log buffer is not true?","o":["The client process records changes in the redo log buffer","The Redo log buffer records changes made to a database","The server process records changes in the redo log buffer","The Redo log buffer records the block that is changed, the location of the change and the new Value."],"c":0,"qv":"Phát biểu nào về Redo log buffer là KHÔNG đúng?","ov":["Tiến trình client ghi các thay đổi vào redo log buffer","Redo log buffer ghi lại các thay đổi đối với CSDL","Tiến trình server ghi các thay đổi vào redo log buffer","Redo log buffer ghi block bị thay đổi, vị trí và giá trị mới"],"ex":"Chính server process (không phải client process) ghi thay đổi vào redo log buffer."},{"id":10,"m":1,"q":"Which of the following is not stored by the Library Cache?","o":["Results of the SQL statements","The text of SQL statement","The Parse Tree: complied version of a statement.","The Execution Plan"],"c":0,"qv":"Mục nào sau đây KHÔNG được lưu trong Library Cache?","ov":["Kết quả của các câu lệnh SQL","Nội dung văn bản câu lệnh SQL","Parse tree: phiên bản đã biên dịch của câu lệnh","Kế hoạch thực thi (Execution Plan)"],"ex":"Library Cache lưu văn bản SQL, parse tree và execution plan, không lưu kết quả truy vấn."},{"id":11,"m":1,"q":"Which of the following is not true about the Shared Pool?","o":["The shared pool can be used by multiple SQL statements for the processing of data retrieved.","Shared Pool is a part of the SGA","Shared Pool consists of the Library cache and the Data dictionary cache","The shared pool is sized by SHARED_POOL_SIZE parameter of  init.ora"],"c":0,"qv":"Phát biểu nào về Shared Pool là KHÔNG đúng?","ov":["Shared pool được nhiều câu lệnh SQL dùng để xử lý dữ liệu đã truy xuất.","Shared Pool là một phần của SGA","Shared Pool gồm Library cache và Data dictionary cache","Kích thước shared pool được đặt bằng tham số SHARED_POOL_SIZE của init.ora"],"ex":"Phát biểu A sai vì shared pool không dùng để chứa dữ liệu đã truy xuất (đó là việc của Data buffer cache)."},{"id":12,"m":1,"q":"Which of the following systems requires a database?","o":["Payroll System","Airline reservations system","A web site that is capturing registered users","All of the above"],"c":3,"qv":"Hệ thống nào sau đây cần có cơ sở dữ liệu?","ov":["Hệ thống tính lương","Hệ thống đặt vé máy bay","Website lưu thông tin người dùng đã đăng ký","Tất cả các hệ thống trên"],"ex":"Cả ba hệ thống đều cần lưu trữ và truy xuất dữ liệu có cấu trúc, nên cần CSDL."},{"id":13,"m":2,"q":"Which of the following is not contained in the Program Global Area?","o":["SQL Execution Plan","Session information","Cursor information","SQL execution work areas"],"c":0,"qv":"","ov":[],"ex":""},{"id":14,"m":11,"q":"Which of the following is not a valid level of abstraction in a DBMS?","o":["Tables","Views","Conceptual Schema","Physical Schema"],"c":0,"qv":"","ov":[],"ex":""},{"id":15,"m":2,"q":"Which of the following is not among the ACID properties of a Transaction?","o":["Independence","Atomicity","Consistency","Durability"],"c":0,"qv":"","ov":[],"ex":""},{"id":16,"m":1,"q":"Which of the following are the advantages of the DBMS over a conventional file system that stores data, in terms of processing power requires a database?","o":["All of the above","Ability to create Data Reports","Efficient Querying of Data","Matching and Sorting"],"c":0,"qv":"","ov":[],"ex":""},{"id":17,"m":1,"q":"Which of the following is not a valid type of a database management system?","o":["OODBMS (Operations Oriented Database Management System)","NDBMS (Networked Database Management System)","HDBMS (Hierarchical Database Management System)","unsigned charRDBMS (Relational Database Management System)"],"c":0,"qv":"","ov":[],"ex":""},{"id":18,"m":1,"q":"Which of the following is not a part of the Oracle Database?","o":["Shared Pool","Data Files","Control Files","Redo Log Files"],"c":0,"qv":"","ov":[],"ex":""},{"id":19,"m":1,"q":"In an instance, multiple ________ can share an SGA.","o":["Server Processes","PMON Processes","Instances","Databases"],"c":2,"qv":"","ov":[],"ex":""},{"id":20,"m":1,"q":"Which component in the following list is not part of the System Global Area (SGA)?","o":["Sort Area","Database Buffer Cache","Library Cache","Shared Pool"],"c":0,"qv":"","ov":[],"ex":""},{"id":21,"m":2,"q":"What does SQL stand for?","o":["Structured Query Language","Structured Question Language","Strong Question Language","Strong Query Language"],"c":0,"qv":"","ov":[],"ex":""},{"id":22,"m":2,"q":"The Employee table contains these columns:\nEmpno  Number(4)\nEname  Varchar2(10)\njob    varchar2(10)\nsal    Varchar2(10)\nYou need to display employee information using this query.\nSELECT Empno, Ename, Job \"Employee Information\" FROM employee;\nHow many columns are presented after executing this query?","o":["2","1","3","0"],"c":1,"qv":"","ov":[],"ex":""},{"id":23,"m":2,"q":"The ITEM table contains these columns:\nITEM_ID  NUMBER(9)\nCOST     NUMBER(7,2)\nRETAIL   NUMBER(7,2)\nThe RETAIL and COST columns contain values greater than zero.\nEvaluate these two SQL statements:\n1. SELECT item_id, (retail * 1.25) + 5.00 - (cost * 1.10) - (cost * .10) AS Calculated Profit\n   FROM item;\n2. SELECT item_id, retail * 1.25 + 5.00 - cost * 1.10 - cost * .10 \"Calculated Profit\"\n   FROM item;\nWhat will be the result?","o":["One of the statements will NOT execute.","Statement 1 will display the 'Calculated Profit' column heading.","Statement 1 and statement 2 will return the same value.","Statement 1 will return a higher value than statement 2."],"c":0,"qv":"","ov":[],"ex":""},{"id":24,"m":6,"q":"Which SQL statement generates the alias Annual Salary for the calculated column SALARY*12?","o":["SELECT ename, salary*12 AS INITCAP ('ANNUAL SALARY') FROM employees;","SELECT ename, salary*12 AS Annual Salary FROM employees;","SELECT ename, salary*12 Annual Salary FROM employees;","SELECT ename, salary*12 'Annual Salary' FROM employees;"],"c":3,"qv":"","ov":[],"ex":""},{"id":25,"m":2,"q":"Evaluate this SQL statement:\nSELECT ename, sal, 12*sal+100 FROM emp;\nThe SAL column stores the monthly salary of the employee. Which change must be made to the above syntax to calculate the annual compensation as \"monthly salary plus a monthly bonus of $100, multiplied by 12\"?","o":["SELECT ename, sal, 12*(sal+100) FROM emp;","No change is required to achieve the desired results","SELECT ename, sal, (12*sal) +100 FROM emp;","SELECT ename, sal+100,*12 FROM emp;"],"c":0,"qv":"","ov":[],"ex":""},{"id":26,"m":2,"q":"You need to produce output that states \"Dear Customer customer_name, \".\nThe customer_name data values come from the CUSTOMER_NAME column in the CUSTOMERS table.\nWhich statement produces this output?","o":["SELECT 'Dear Customer ' customer_name ',' FROM customers;","SELECT dear customer, customer_name, FROM customers;","SELECT \"Dear Customer\", customer_name ',' FROM customers;","SELECT 'Dear Customer '  customer_name ',' FROM customers;"],"c":0,"qv":"","ov":[],"ex":""},{"id":27,"m":4,"q":"Which of the following query will correctly display each row of the Employees table only once given that Employees table may contain duplicate rows?","o":["SELECT distinct * from employees;","SELECT unique rows from employees;","SELECT * from employees;","SELECT distinct rows from employees;"],"c":0,"qv":"","ov":[],"ex":""},{"id":28,"m":2,"q":"What will be the output of the following query?\nSELECT 1 FROM employees;","o":["This statement will return 1 as many times as the number of rows in the employees table.","This statement will return first row of the employees table","This statement will return only one row and one column in output and value will be 1.","This statement will return error."],"c":0,"qv":"","ov":[],"ex":""},{"id":29,"m":2,"q":"What of the following statements is not true?","o":["Clauses must be placed on separate lines.","SQL statements are not case sensitive.","SQL statements can be on one or more lines.","Keywords cannot be abbreviated or split across lines."],"c":0,"qv":"","ov":[],"ex":""},{"id":30,"m":2,"q":"What is true about NULL?","o":["NULL is a value that is unavailable, unassigned, unknown, or inapplicable","NULL is same as blank spaces","NULL in a number column can be treated as zero","NULL means an incorrect value"],"c":0,"qv":"","ov":[],"ex":""},{"id":31,"m":7,"q":"What should be the result of the expression for the employees having commission_pct as NULL?\nSELECT 12 * salary * commission_pct 'ANNSAL_COMM'\nFROM employees;","o":["None of the above","Zero","NULL","Unpredictable"],"c":2,"qv":"","ov":[],"ex":""},{"id":32,"m":1,"q":"Which SQL statement is used to extract data from a database?","o":["SELECT","GET","OPEN","EXTRACT"],"c":0,"qv":"","ov":[],"ex":""},{"id":33,"m":3,"q":"Which statement about the column aliases is not True?","o":["\"AS\" keyword must be used between the column name and the column alias","A column alias renames a column heading","A column alias requires double quotation marks if it contains spaces or special characters or is case sensitive","Immediately follows the column name."],"c":0,"qv":"","ov":[],"ex":""},{"id":34,"m":2,"q":"With SQL, how do you select a column named \"FirstName\" from a table named \"Persons\"?","o":["SELECT Persons.FirstName ;","SELECT FirstName FROM Persons;","EXTRACT FirstName FROM Persons ;","SELECT FROM persons the FirstName;"],"c":1,"qv":"","ov":[],"ex":""},{"id":35,"m":2,"q":"In the following query, which expression is evaluated first?\nSELECT id_number, (quantity - 100 / 0.15 + 20 - 10) FROM inventory","o":["D.\t20 - 10","0.15 + 20","100 / 0.15","quantity - 100"],"c":2,"qv":"","ov":[],"ex":""},{"id":36,"m":4,"q":"Which SQL statement is used to return only different values?","o":["SELECT DISTINCT","SELECT DIFFERENT","SELECT UNIQUE","SELECT NO DUPLICATES"],"c":0,"qv":"","ov":[],"ex":""},{"id":37,"m":2,"q":"Which clauses of a SELECT statement are mandatory?","o":["SELECT and FROM","Only SELECT","SELECT and WHERE","SELECT, FROM and WHERE"],"c":0,"qv":"","ov":[],"ex":""},{"id":38,"m":4,"q":"Which SELECT statement should you use if you want to display unique combinations of the POSITION and MANAGER values from the EMPLOYEE table?","o":["SELECT position, manager DISTINCT FROM employee;","SELECT DISTINCT position, manager FROM employee;","SELECT position, manager FROM employee;","SELECT position, DISTINCT manager FROM employee;"],"c":1,"qv":"","ov":[],"ex":""},{"id":39,"m":2,"q":"You are formulating queries in a SQL* Plus.\nWhich of the following statement correctly describes how to specify a column alias?","o":["Place the alias at the end of the statement to describe the table.","Place the alias after each column separated by a comma to describe the column.","Place the alias after each column separated by a space to describe the column.","Place the alias at the beginning of the statement to describe the table."],"c":2,"qv":"","ov":[],"ex":""},{"id":40,"m":2,"q":"With SQL, how do you select all the columns from a table named \"Persons\"?","o":["SELECT *.Persons","SELECT Persons","SELECT [all] FROM Persons","SELECT * FROM Persons"],"c":3,"qv":"","ov":[],"ex":""},{"id":41,"m":3,"q":"What does the TRUNCATE statement do?","o":["Removes the table","Removes all rows from a table","Shortens the table to 10 rows","Removes all columns from a table"],"c":0,"qv":"","ov":[],"ex":""},{"id":42,"m":3,"q":"Which statement about data types is true?","o":["The CHAR datatype should be used for fixed-length character data","The TIMESTAMP data type is an extension of the VARCHAR2 data type","The BLOB data type stores character data up to four gigabytes","The VARCHAR2 data type stores character data up to four gigabytes"],"c":0,"qv":"","ov":[],"ex":""},{"id":43,"m":3,"q":"The EMPLOYEES table has these columns:\nLAST_NAME  VARCHAR2(35)\nSALARY     NUMBER(8,2)\nHIRE_DATE  DATE\nManagement wants to add a default value to the SALARY column. You plan to alter the table by using this SQL statement:\nALTER TABLE EMPLOYEES\nMODIFY (SALARY DEFAULT 5000);\nWhat is true about your ALTER statement?","o":["A change to the DEFAULT value affects only subsequent insertions to the table.","Column definitions cannot be altered to add DEFAULT values.","Column definitions cannot be altered at add DEFAULT values for columns with a NUMBER data type","All the rows that have a NULL value for the SALARY column will be updated with the value5000."],"c":0,"qv":"","ov":[],"ex":""},{"id":44,"m":3,"q":"You need to change the definition of an existing table. The COMMERCIALS table needs its DESCRIPTION column changed to hold varying length characters up to 2000 bytes. The column can currently hold 1000 bytes per value. The table contains 20000 rows.\nWhich statement is valid?","o":["ALTER TABLE commercials MODIFY (description VARCHAR2(2000));","ALTER TABLE commercials MODIFY (description CHAR2(2000));","ALTER TABLE commercials CHANGE (description CHAR2(2000));","ALTER TABLE commercials CHANGE (description VARCHAR2(2000));"],"c":0,"qv":"","ov":[],"ex":""},{"id":45,"m":11,"q":"Evaluate the SQL statement:\nDROP TABLE DEPT;\nWhich statement is false about the above SQL statement?","o":["All views based on the DEPT table are deleted.","You cannot roll back this statement.","All pending transactions are committed.","All indexes based on the DEPT table are dropped."],"c":0,"qv":"","ov":[],"ex":""},{"id":46,"m":12,"q":"Which statement describes the ROWID data type?","o":["A hexadecimal string representing the unique address of a row in its table.","Binary data up to 4 gigabytes","Character data up to 4 gigabytes.","Raw binary data of variable length up to 2 gigabytes."],"c":0,"qv":"","ov":[],"ex":""},{"id":47,"m":3,"q":"You just issued the following statement.\nALTER TABLE marketing\nDROP COLUMN profit;\nWhich of the following choices identified when the column will actually be removed from database?","o":["Immediately following statement execution.","After the Alter table drop unused columns command is issued.","After the Alter table set unused column command is issued.","After the Alter table modify command is issued."],"c":0,"qv":"","ov":[],"ex":""},{"id":48,"m":2,"q":"Which of the following can be a valid table name?","o":["Catch_#22","Number","1966_Invoices","#Invoices"],"c":0,"qv":"","ov":[],"ex":""},{"id":49,"m":1,"q":"Which describes the default behaviour when you create a table?","o":["Tables are created in your schema.","The table is accessible to all users.","Tables are created in the public schema.","Tables are created in the DBA schema."],"c":0,"qv":"","ov":[],"ex":""},{"id":50,"m":4,"q":"You need to modify the STUDENTS table to add a primary key on the STUDENT_ID column. The table is currently empty. Which statement accomplishes this task?","o":["ALTER TABLE students ADD CONSTRAINT stud_id_pk PRIMARY KEY (student_id);","ALTER TABLE students ADD PRIMARY KEY student_id;","ALTER TABLE students ADD CONSTRAINT PRIMARY KEY (student_id);","ALTER TABLE students ADD CONSTRAINT stud_id_pk PRIMARY KEY student_id;"],"c":0,"qv":"","ov":[],"ex":""},{"id":51,"m":9,"q":"Evaluate the SQL statement:\nTRUNCATE TABLE DEPT;\nWhich statement is not true about the SQL statement?","o":["It releases the storage space used by the table.","It does not release the storage space used by the table.","You can NOT roll back the deletion of rows after the statement executes.","You must be the owner of the table or have DELETE ANY TABLE system privileges to truncate the DEPT table"],"c":0,"qv":"","ov":[],"ex":""},{"id":52,"m":1,"q":"Which is not a correct guideline for naming database tables?","o":["Must begin with either a number or a letter.","Must be 1-30 characters long.","Should not be an Oracle Server reserved word.","Must contain only A-Z, a-z, 0-9, _, $, and #."],"c":0,"qv":"","ov":[],"ex":""},{"id":53,"m":3,"q":"Which is a valid CREATE TABLE statement?","o":["CREATE TABLE EMP9$# AS (empid number(2));","CREATE TABLE EMP*123 AS (empid number(2));","CREATE TABLE PACKAGE AS (packid num(2));","CREATE TABLE EMP_TEST AS (empid number(2));"],"c":0,"qv":"","ov":[],"ex":""},{"id":54,"m":3,"q":"Which of these DATETIME data types cannot be used when specifying column definitions?","o":["INTERVAL MONTH TO DAY","TIMESTAMP","INTERVAL DAY TO SECOND","INTERVAL YEAR TO MONTH"],"c":0,"qv":"","ov":[],"ex":""},{"id":55,"m":1,"q":"Which statement about a table is true?","o":["The size of a table does NOT need to be specified","A table can have up to 10,000 columns","A table CANNOT be created while users are using the database.","The structure of a table CANNOT be modified while the table is online."],"c":0,"qv":"","ov":[],"ex":""},{"id":56,"m":3,"q":"Consider a general employees table, which statement should you use to increase the EMP_LNAME column length to 25 if the column currently contains 3000 records?","o":["ALTER TABLE employee MODIFY emp_lname VARCHAR2(25);","You CANNOT increases the width of the EMP_LNAME column.","ALTER TABLE employee RENAME emp_lname VARCHAR2(25);","ALTER employee TABLE MODIFY COLUMN emp_lname VARCHAR2(25);"],"c":0,"qv":"","ov":[],"ex":""},{"id":57,"m":3,"q":"Which statement will permanently remove all the data in, the indexes on, and the structure of the PO_DETAIL table?","o":["DROP TABLE po_detail;","DELETE TABLE po_detail;","TRUNCATE TABLE po_detail;","ALTER TABLE po_detail SET UNUSED (po_num, po_line_id, product_id, quantity, unit_price);"],"c":0,"qv":"","ov":[],"ex":""},{"id":58,"m":3,"q":"Consider an Employees table in which the MGR_ID column currently contains employee identification numbers, and you need to allow users to include text characters in the identification values. Which statement should you use to implement this?","o":["You CANNOT modifies the data type of the MGR_ID column.","ALTER employee MODIFY (mgr_id VARCHAR2(15));","ALTER TABLE employee MODIFY (mgr_id VARCHAR2(15));","ALTER employee TABLE MODIFY COLUMN (mgr_id VARCHAR2(15));"],"c":0,"qv":"","ov":[],"ex":""},{"id":59,"m":3,"q":"Which CREATE TABLE statements will not fail?","o":["CREATE TABLE time (time1 NUMBER(9));","CREATE TABLE date (time_id NUMBER(9));","CREATE TABLE time* (time_id NUMBER(9));","CREATE TABLE $time (time_id NUMBER(9));"],"c":0,"qv":"","ov":[],"ex":""},{"id":60,"m":4,"q":"Examine the structure of the PRODUCT table.\nPRODUCT_ID    NUMBER        Primary Key\nPRODUCT_NAME  VARCHAR2(25)\nSUPPLIER_ID   NUMBER\nLIST_PRICE    NUMBER(7,2)\nYou need to reduce the LIST_PRICE column precision to 6 with a scale of 2 and ensure that when inserting a row into the PRODUCT table without a value for the LIST_PRICE column, a price of $5.00 will automatically be inserted. The PRODUCT table currently contains no records.\nWhich statement should you use?","o":["ALTER TABLE product MODIFY (list_price NUMBER(6,2) DEFAULT 5);","ALTER TABLE product ADD OR REPLACE (list_price NUMBER(8,2) DEFAULT 5);","ALTER TABLE product MODIFY COLUMN (list_price NUMBER(6,2) DEFAULT '$5.00');","You CANNOT reduces the size of the LIST_PRICE column."],"c":0,"qv":"","ov":[],"ex":""},{"id":61,"m":4,"q":"Which ALTER TABLE statement should you use to add a PRIMARY KEY constraint on the MANUFACTURER_ID column of the INVENTORY table?","o":["ALTER TABLE inventory ADD PRIMARY KEY (manufacturer_id);","ALTER TABLE inventory ADD CONSTRAINT manufacturer_id PRIMARY KEY;","ALTER TABLE inventory MODIFY manufacturer_id CONSTRAINT PRIMARY KEY;","ALTER TABLE inventory MODIFY CONSTRAINT PRIMARY KEY manufacturer_id;"],"c":0,"qv":"","ov":[],"ex":""},{"id":62,"m":4,"q":"Which statement explicitly names a constraint?","o":["ALTER TABLE student_grades ADD CONSTRAINT student_id_fk FOREIGN KEY (student_id) REFERENCES students(student_id);","ALTER TABLE student_grades ADD FOREIGN KEY (student_id) REFERENCES students(student_id);","ALTER TABLE student_grades ADD CONSTRAINT NAME = student_id_fk FOREIGN KEY (student_id) REFERENCES students(student_id);","ALTER TABLE student grades ADD NAMED CONSTRAINT student_id_fk FOREIGN KEY (student_id) REFERENCES students(student_id);"],"c":0,"qv":"","ov":[],"ex":""},{"id":63,"m":4,"q":"Examine the SQL statements that create ORDERS table:\nCREATE TABLE orders\n(SER_NO      NUMBER UNIQUE,\n ORDER_ID    NUMBER,\n ORDER_DATE  DATE NOT NULL,\n STATUS      VARCHAR2(10)\n             CHECK (status IN ('CREDIT', 'CASH')),\n PROD_ID     NUMBER\n             REFERENCES PRODUCTS(PRODUCT_ID),\n ORD_TOTAL   NUMBER\n);\nFor which columns would an index be automatically created when you execute the above SQL statement?","o":["SER_NO","ORDER_ID","STATUS","PROD_ID"],"c":0,"qv":"","ov":[],"ex":""},{"id":64,"m":4,"q":"For which of these constraints does the Oracle Server implicitly create a unique index?","o":["PRIMARY KEY","NOT NULL","FOREIGN KEY","CHECK"],"c":0,"qv":"","ov":[],"ex":""},{"id":65,"m":4,"q":"Your attempt to disable a constraint results in the following error:\nORA-02297: cannot disable constraint - dependencies exist.\nWhich of the following types of the constraints is likely causing interference with your disablement of this one?","o":["Foreign key Constraints","Check constraints","Not NULL constraints.","Unique Constraints."],"c":0,"qv":"","ov":[],"ex":""},{"id":66,"m":4,"q":"Which is not a valid Oracle constraint type?","o":["CASCADE","UNIQUE","CHECK","NOT NULL"],"c":0,"qv":"","ov":[],"ex":""},{"id":67,"m":4,"q":"Which constraint will ensure that the CUSTOMER_NAME column of the CUSTOMERS table always holds a value?","o":["NOT NULL or Primary Key","Only Primary Key","Unique","Foreign Key"],"c":0,"qv":"","ov":[],"ex":""},{"id":68,"m":11,"q":"Which view should a user query to display the columns associated with the constraints on a table owned by the user?","o":["USER_CONS_COLUMNS","USER_CONSTRAINTS","USER_OBJECTS","ALL_CONSTRAINTS"],"c":0,"qv":"","ov":[],"ex":""},{"id":69,"m":4,"q":"You need to modify the STUDENTS table to add a primary key on the STUDENT_ID column. The table is currently empty. Which statement accomplishes this task?","o":["ALTER TABLE students ADD CONSTRAINT stud_id_pk PRIMARY KEY (student_id);","ALTER TABLE students ADD PRIMARY KEY student_id;","ALTER TABLE students ADD CONSTRAINT PRIMARY KEY (student_id);","ALTER TABLE students ADD CONSTRAINT stud_id_pk PRIMARY KEY student_id;"],"c":0,"qv":"","ov":[],"ex":""},{"id":70,"m":4,"q":"Which statement about the CASCADE CONSTRAINTS clause is not true?","o":["The CASCADE CONSTRAINTS can be used while creating the constraint to enable automatic dropping of foreign key constraint when a primary key is dropped.","The CASCADE CONSTRAINTS clause is used along with the DROP COLUMN clause.","The CASCADE CONSTRAINTS clause drops all referential integrity constraints that refer to the primary and unique keys defined on the dropped columns.","The CASCADE CONSTRAINTS clause also drops all multicolumn constraints defined on the dropped columns"],"c":0,"qv":"","ov":[],"ex":""},{"id":71,"m":11,"q":"Which data dictionary view can be used to view the details of columns involved in constraints ?","o":["USER_CONS_COLUMNS","USER_COLS_CONSTRAINTS","USER_CONSTRAINTS","USER_OBJECTS"],"c":0,"qv":"","ov":[],"ex":""},{"id":72,"m":4,"q":"Which SQL statement defines the FOREIGN KEY constraint on the DEPTNO column of the EMP table?","o":["CREATE TABLE EMP(empno NUMBER(4),ename VARCNAR2(35),deptno NUMBER(7,2) CONSTRAINT emp_deptno_fk REFERENCES dept (deptno));","CREATE TABLE EMP(empno NUMBER(4),ename VARCNAR2(35),deptno NUMBER(7,2) NOT NULL CONSTRAINT emp_deptno_fk FOREIGN KEY deptno REFERENCES dept deptno);","CREATE TABLE EMP(empno NUMBER(4)ename VARCHAR2(35),deptno NUMBER(7,2) NOT NULL, CONSTRAINT emp_deptno_fk REFERENCES dept (deptno) FOREIGN KEY (deptno));","CREATE TABLE EMP (empno NUMBER(4),ename VARCNAR2(35),deptno NUMBER(7,2) FOREIGN KEY CONSTRAINT emp deptno fk REFERENCES dept (deptno));"],"c":0,"qv":"","ov":[],"ex":""},{"id":73,"m":4,"q":"Which statement should be used to alter the constraints (i.e. either to enable, disable or drop a constraint)?","o":["ALTER TABLE","ALTER CONSTRAINT","DROP CONSTRAINT","ALTER OBJECT"],"c":0,"qv":"","ov":[],"ex":""},{"id":74,"m":11,"q":"Which statement is not correct about the use of constraints?","o":["Constraints make complex queries easy","Constraints enforce rules at the view level.","Constraints enforce rules at the table level.","Constraints prevent the deletion of a table if there are dependencies."],"c":0,"qv":"","ov":[],"ex":""},{"id":75,"m":4,"q":"Which statement about NOT NULL constraints is true?","o":["NOT NULL constraints can only be defined at the column level.","You CANNOT add a NOT NULL constraint to an existing column using the ALTER TABLE statement","You can modify the structure of a NOT NULL constraint using the ALTER TABLE statement.","A NOT NULL constraint is stored in the data dictionary as a UNIQUE constraint."],"c":0,"qv":"","ov":[],"ex":""},{"id":76,"m":9,"q":"The PO_DETAIL table contains these columns:\nPO_NUM      NUMBER  NOT NULL, Primary Key\nPO_LINE_ID  NUMBER  NOT NULL, Primary Key\nPRODUCT_ID  NUMBER  Foreign Key to PRODUCT_ID column of the PRODUCT table\nQUANTITY    NUMBER\nUNIT_PRICE  NUMBER(5,2)\nEvaluate this statement:\nALTER TABLE po_detail\nENABLE CONSTRAINT po_num_pk;\nFor which task would you issue this statement?","o":["to activate the previously disabled constraint on the PO_NUM column while creating a PRIMARY KEY index","to drop and recreate the PRIMARY KEY constraint on the PO_NUM column","to create a new PRIMARY KEY constraint on the PO_NUM column","to enable any previously disabled FOREIGN KEY constraints that are dependent on thePO_NUM column"],"c":0,"qv":"","ov":[],"ex":""},{"id":77,"m":4,"q":"Which statement about constraints is true?","o":["Constraints prevent a table with dependencies from being deleted.","Constraints only enforce rules at the table level.","You must provide a name for each constraint at the time of its creation.","Constraint names are NOT required to follow the standard object-naming rules."],"c":0,"qv":"","ov":[],"ex":""},{"id":78,"m":4,"q":"Which syntax turns an existing constraint on?","o":["ALTER TABLE table_name ENABLE CONSTRAINT constraint_name;","ALTER TABLE table_name ENABLE constraint_name;","ALTER TABLE table_name STATUS = ENABLE CONSTRAINT constraint_name;","ALTER TABLE table_name STATUS ENABLE CONSTRAINT constraint_name;"],"c":0,"qv":"","ov":[],"ex":""},{"id":79,"m":11,"q":"Which statement about creating constraints is true?","o":["Constraints can be created after the table is created.","Constraint names must start with SYS_C.","All constraints must be defines at the column level.","Information about constraints is found in the VIEW_CONSTRAINTS dictionary view."],"c":0,"qv":"","ov":[],"ex":""},{"id":80,"m":4,"q":"Which constraint can be defined only at the column level?","o":["NOT NULL","UNIQUE","CHECK","PRIMARY KEY"],"c":0,"qv":"","ov":[],"ex":""},{"id":81,"m":2,"q":"A data manipulation language statement _____.","o":["Modifies the data but not the structure of a table","Completes a transaction on a table.","Modifies the structure and data in a table","Modifies the structure but not the data of a table"],"c":0,"qv":"","ov":[],"ex":""},{"id":82,"m":5,"q":"Which statement regarding DML statement functionality is true?","o":["UPDATE can update multiple columns in one table.","DELETE can be used to delete rows or columns from a table.","MERGE will delete rows that do NOT exist in either table.","UPDATE will add rows to a table if an INTO clause is specified."],"c":0,"qv":"","ov":[],"ex":""},{"id":83,"m":4,"q":"You own a table called EMPLOYEES. What happens when you execute this DELETE statement?\nDELETE employees;","o":["The data in the EMPLOYEES table is deleted but not the structure.","You get an error because of a primary key violation","The data and structure of the EMPLOYEES table are deleted.","You get an error because the statement is not syntactically correct."],"c":0,"qv":"","ov":[],"ex":""},{"id":84,"m":4,"q":"Examine the structure of the EMPLOYEES table:\nEMPLOYEE_ID  NUMBER        Primary Key\nFIRST_NAME   VARCHAR2(25)\nLAST_NAME    VARCHAR2(25)\nWhich statement fails to insert a row into the table?","o":["INSERT INTO employees( first_name, last_name) VALUES( 'John', 'Smith');","INSERT INTO employees VALUES ( '1000', 'John', NULL);","INSERT INTO employees (employee_id) VALUES (1000);","INSERT INTO employees (employee_id, first_name, last_name) VALUES ( 1000, 'John', ' ');"],"c":0,"qv":"","ov":[],"ex":""},{"id":85,"m":5,"q":"Which is not true?","o":["A MERGE statement replaces the complete data of one table with that of another.","A MERGE statement is used to merge the data of one table with data from another.","A MERGE statement can be used to insert new rows into a table.","A MERGE statement can be used to update existing rows in a table."],"c":0,"qv":"","ov":[],"ex":""},{"id":86,"m":5,"q":"With SQL, how can you insert \"Olsen\" as the \"LastName\" in the \"Persons\" table?","o":["INSERT INTO Persons (LastName) VALUES ('Olsen')","INSERT INTO Persons ('Olsen') as LastName","INSERT LastName('Olsen') INTO Persons","None of the above"],"c":0,"qv":"","ov":[],"ex":""},{"id":87,"m":5,"q":"How can you change \"Hansen\" into \"Nilsen\" in the \"LastName\" column in the Persons table?","o":["UPDATE Persons SET LastName='Nilsen' WHERE LastName='Hansen'","MODIFY Persons SET LastName='Hansen' INTO LastName='Nilsen","UPDATE Persons SET LastName='Hansen' INTO LastName='Nilsen'","MODIFY Persons SET LastName='Nilsen' WHERE LastName='Hansen'"],"c":0,"qv":"","ov":[],"ex":""},{"id":88,"m":5,"q":"With SQL, how can you delete the records where the \"FirstName\" is \"Peter\" in the Persons Table?","o":["DELETE FROM Persons WHERE FirstName = 'Peter'","DELETE * FROM Persons WHERE FirstName = 'Peter'","DELETE FirstName FROM Persons WHERE FirstName = 'Peter'","DELETE 'Peter' FROM Persons"],"c":0,"qv":"","ov":[],"ex":""},{"id":89,"m":5,"q":"Which of the following Insert statement will successfully insert only records of Sales Representatives from the employees table into a new table called Sales_rep ?","o":["INSERT INTO sales_reps(id, name, salary, commission_pct) SELECT employee_id, last_name, salary, commission_pct FROM employees WHERE job_id = 'SA_REP';","INSERT INTO sales_reps(id, name, salary, commission_pct) VALUES SELECT employee_id, last_name, salary, commission_pct FROM employees WHERE job_id = 'SA_REP';","INSERT INTO sales_reps(id, name, salary, commission_pct) SELECT employee_id, last_name, salary, commission_pct FROM employees;","INSERT INTO sales_reps(id, name, salary, commission_pct) SELECT last_name, employee_id, salary, commission_pct FROM employees WHERE job_id = 'SA_REP';"],"c":0,"qv":"","ov":[],"ex":""},{"id":90,"m":10,"q":"Which of the following is not a valid usage of a Merge statement?","o":["Insert as well as update each row in a table.","Conditionally update or insert data into a database table","Perform an UPDATE if the row exists, and an INSERT if it is a new row","Increase performance and ease of use"],"c":0,"qv":"","ov":[],"ex":""},{"id":91,"m":5,"q":"What will be the output of following statement?\nUPDATE employees a\nSET job_id = (SELECT job_id\n              FROM new_employees b\n              WHERE a.employee_id = b.employee_id);\nAssume that Employee and New_employees tables have same structure.","o":["This statement will update job_id for all records of employees as:Match found in New_employees table use job_id from New_employees tableno match found in New_employees table update job_id as NULL.","This statement will return error","This statement will update only those records of Employees table which have matching employee_id in the New_employees table.","This statement will update job_id for all records of employees table but for records that do not have matching employee_id in the New_employees table the existing job_id will be retained."],"c":0,"qv":"","ov":[],"ex":""},{"id":92,"m":5,"q":"Which of the following is not a DML statement?","o":["COMMIT","MERGE","UPDATE","DELETE"],"c":0,"qv":"","ov":[],"ex":""},{"id":93,"m":5,"q":"What will be the output of following statement?\nINSERT INTO departments (department_id, department_name, manager_id)\nVALUES (300, 'Engineering', DEFAULT);","o":["This will insert one record in Employees table with values (300, 'Engineering') for the (department_id, department_name) respectively.","This will insert one record in Employees table with values (300, 'Engineering', DEFAULT) for the (department_id, department_name, manager_id) respectively","This will insert one record in Employees table with values (300, 'Engineering') for the (department_id, department_name) respectively manager_id will be NULL as DEFAULT is not a valid value.","This will return Error as DEFAULT is not allowed in the INSERT"],"c":0,"qv":"","ov":[],"ex":""},{"id":94,"m":10,"q":"You maintain two tables, CUSTOMER and PROSPECT, that have identical structures but different data. You want to synchronize these two tables by inserting records from the PROSPECT table into the CUSTOMER table, if they do not exist. If the customer already exists in the CUSTOMER table, you want to update customer data.\nWhich DML statement should you use to perform this task?","o":["MERGE","INSERT","UPDATE","You CANNOT perform this task with one DML operation."],"c":0,"qv":"","ov":[],"ex":""},{"id":95,"m":3,"q":"You added a PHONE-NUMBER column of NUMBER data type to an existing EMPLOYEES table.\nThe EMPLOYEES table already contains records of 100 employees. Now, you want to enter the phone numbers of each of the 100 employees into the table. Some of the employees may not have a phone number available.\nWhich data manipulation operation do you perform?","o":["PDATE","MERGE","INSERT","ADD"],"c":0,"qv":"","ov":[],"ex":""},{"id":96,"m":4,"q":"Evaluate this DELETE statement:\nDELETE employee_id, salary, job_id\nFROM employees\nWHERE dept_id = 90;\nWhy does the DELETE statement fail when you execute it?","o":["You cannot specify column names in the DELETE clause of the DELETE statement.","There is no row with dept_id 90 in the EMPLOYEES table.","You cannot delete the JOB_ID column because it is a NOT NULL column.","You cannot delete the EMPLOYEE_ID column because it is the primary key of the table."],"c":0,"qv":"","ov":[],"ex":""},{"id":97,"m":4,"q":"Examine the structure of the EMPLOYEES table:\nEMPLOYEE_ID  NUMBER        Primary Key\nFIRST_NAME   VARCHAR2(25)\nLAST_NAME    VARCHAR2(25)\nWhich statement inserts a row into the table?","o":["INSERT INTO employees VALUES ('1000','John',NULL);","INSERT INTO employees VALUES ( NULL, 'John','Smith');","INSERT INTO employees( first_name, last_name) VALUES('John','Smith');","INSERT INTO employees(first_name,last_name, employee_id) VALUES ( 1000, 'John','Smith');"],"c":0,"qv":"","ov":[],"ex":""},{"id":98,"m":8,"q":"Examine the data from the CLASS and INSTRUCTOR tables.\nCLASS Table\nCLASS_ID  CLASS_NAME                  HOURS_CREDIT  INSTRUCTOR_ID\n--------  --------------------------  ------------  -------------\n1         Introduction to Accounting  3             4\n2         Computer Basics             3             1\n3         Tax Accounting Principles   3             4\n4         American History            3             2\n5         Basic Engineering           3\nYou want to delete the classes that do NOT have an instructor assigned. Which DELETE statement will accomplish the desired result?","o":["DELETE FROM class WHERE instructor_id IS NULL;","DELETE class_id, class_name, hours_credit, instructor_id FROM class WHERE instructor_id IS NULL;","DELETE FROM class WHERE instructor_id NOT IN(SELECT instructor_id FROM class);","DELETE FROM instructor NATURAL JOIN class WHERE instructor_id IS NOT NULL;"],"c":0,"qv":"","ov":[],"ex":""},{"id":99,"m":4,"q":"The PRODUCT table contains these columns:\nPRODUCT_ID    NUMBER  NOT NULL\nPRODUCT_NAME  VARCHAR2(25)\nSUPPLIER_ID   NUMBER\nLIST_PRICE    NUMBER(7,2)\nCOST          NUMBER(7,2)\nYou need to increase the list price and cost of all products supplied by Global Imports, Inc. by 5.5 percent. The SUPPLIER_ID for Global Imports, Inc. is 105. Which statement should you use?","o":["UPDATE product SET list_price = list_price * 1.055, cost = cost * 1.055 WHERE supplier_id = 105;","UPDATE product SET list_price = list_price * 1.055 SET cost = cost * 1.055 WHERE supplier_id = 105;","UPDATE product","UPDATE product SET list_price = list_price + (list_price * .055), cost = cost + (cost * .055) WHERE supplier_id LIKE 'Global Imports, Inc.' OR supplier_id = 105;"],"c":0,"qv":"","ov":[],"ex":""},{"id":100,"m":8,"q":"Examine the structures of the EVENT and NEW_EVENT tables.\nEVENT Table\nEVENT_ID           NUMBER\nEVENT_NAME         VARCHAR2(30)\nEVENT_DESCRIPTION  VARCHAR2(100)\nEVENT_TYPE_ID      NUMBER\nNEW_EVENT Table\nEVENT_ID           NUMBER\nEVENT_NAME         VARCHAR2(30)\nEVENT_DESCRIPTION  VARCHAR2(100)\nEVENT_TYPE_ID      NUMBER\nSTART_DT           DATE\nYou execute this MERGE statement:\nMERGE INTO event e\nUSING (SELECT *\n       FROM new_event\n       WHERE event_type_id = 4) n\nON (e.event_id = n.event_id)\nWHEN MATCHED THEN\n  UPDATE SET\n    e.event_type_id = n.event_type_id,\n    e.start_dt = n.start_dt\nWHEN NOT MATCHED THEN\n  INSERT (event_id, event_name, event_type_id)\n  VALUES (n.event_id, n.event_name, n.event_type_id);\nThis MERGE statement generates an error. Which statement describes the cause of the error?","o":["The UPDATE portion of the statement is invalid.","A subquery CANNOT be used in the USING clause of a MERGE statement.","Table aliases CANNOT be used in a MERGE statement.","The ON clause of the statement is invalid."],"c":0,"qv":"","ov":[],"ex":""},{"id":101,"m":6,"q":"You want to use a function in your column clause of a SQL statement.\nThe NVL function accomplishes which of the following tasks?","o":["Enables you to specify alternated out for NULL column values.","Assists in the distribution of output across multiple columns.","Enables you to specify alternate output for non-NULL column values.","Nullifies the value of the column output."],"c":0,"qv":"","ov":[],"ex":""},{"id":102,"m":6,"q":"Which SELECT statement will show the result 'elloworld' from the string 'HelloWorld'?","o":["SELECT LOWER (TRIM ('H' FROM 'HelloWorld')) FROM dual;","SELECT SUBSTR ('HelloWorld', 1) FROM dual;","SELECT INITCAP (TRIM ('HelloWorld', 1, 1)) FROM dual;","SELECT LOWER (SUBSTR ('HelloWorld', 1, 1) FROM dual;"],"c":0,"qv":"","ov":[],"ex":""},{"id":103,"m":6,"q":"Which script displays '01-JAN-02' when the ENROLL_DATE value is '01-JUL-01'?","o":["SELECT ROUND (enroll_date, 'YEAR') FROM student;","SELECT ROUND (enroll_date, 'DAY') FROM student;","SELECT ROUND (enroll_date, 'MONTH') FROM student;","SELECT ROUND (TO_CHAR(enroll_date, 'YYYY')) FROM student;"],"c":0,"qv":"","ov":[],"ex":""},{"id":104,"m":6,"q":"Which function can be used in your query on department table to restrict the data displayed to only those department names containing 3 characters?","o":["LENGTH","REPLACE","SUBSTR","RPAD"],"c":0,"qv":"","ov":[],"ex":""},{"id":105,"m":3,"q":"Which statement concerning SQL functions is true?","o":["Character functions can return character or number values.","Conversion functions convert a column definition from one data type to another data type.","Single-row functions can only be used in SELECT and WHERE clauses.","All date functions return DATE data type values."],"c":0,"qv":"","ov":[],"ex":""},{"id":106,"m":6,"q":"Evaluate the SQL statement:\nSELECT ROUND(45.953, -1), TRUNC(45.936, 2)\nFROM dual;\nWhich values are displayed?","o":["50 and 45.93","46 and 45","46 and 45.93","50 and 45.9"],"c":0,"qv":"","ov":[],"ex":""},{"id":107,"m":6,"q":"Which of the following is not a number function?","o":["TO_NUMBER.","TRUNC","SQRT","ROUND"],"c":0,"qv":"","ov":[],"ex":""},{"id":108,"m":12,"q":"You are using single row function in a SELECT statement which function can best be categorized as similar in function to an IF-THEN-ELSE statement?","o":["DECODE","SQRT","NEW_TIME","ROWIDTOCHAR."],"c":0,"qv":"","ov":[],"ex":""},{"id":109,"m":6,"q":"Which is not an attributes of single row functions?","o":["cannot be nested","manipulate data items","act on each row returned","return one result per row"],"c":0,"qv":"","ov":[],"ex":""},{"id":110,"m":7,"q":"Which SQL statement returns a numeric value?","o":["SELECT sysdate-hire_date FROM EMP;","SELECT ADD_MONTHS(MAX(hire_Date), 6) FROM EMP;","SELECT ROUND(hire_date) FROM EMP;","SELECT TO_NUMBER(hire_date + 7) FROM EMP;"],"c":0,"qv":"","ov":[],"ex":""},{"id":111,"m":6,"q":"Which is not a type of Single Row functions available in SQL?","o":["calendar","string","character","Numeric"],"c":0,"qv":"","ov":[],"ex":""},{"id":112,"m":4,"q":"Management has asked you to calculate the value 12*salary*commission_pct for all the employees in the EMP table.\nThe EMP table contains these columns:\nLAST_NAME       VARCHAR2(35)  NOT NULL\nSALARY          NUMBER(9,2)   NOT NULL\nCOMMISSION_PCT  NUMBER(4,2)\nWhich statement ensures that a value is displayed in the calculated columns for all employees?","o":["SELECT last_name, 12*salary*(nvl(commission_pct,0)) FROM emp;","SELECT last_name, 12*salary*commison_pct FROM emp;","SELECT last_name, 12*salary* (commission_pct,0) FROM emp;","SELECT last_name, 12*salary*(decode(commission_pct,0)) FROM emp;"],"c":0,"qv":"","ov":[],"ex":""},{"id":113,"m":6,"q":"Evaluate the SQL statement:\nSELECT LPAD(salary, 10, *)\nFROM EMP\nWHERE EMP_ID = 1001;\nIf the employee with the EMP_ID 1001 has a salary of 17000, what is displayed?","o":["An error statement","17000.00","17000*****","*****17000"],"c":0,"qv":"","ov":[],"ex":""},{"id":114,"m":6,"q":"The EMPLOYEE table has these columns:\nLAST_NAME       VARCHAR2(35)\nSALARY          NUMBER(8,2)\nCOMMISSION_PCT  NUMBER(5,2)\nYou want to display the name and annual salary multiplied by the commission_pct for all employees. For records that have a NULL commission_pct, a zero must be displayed against the calculated column. Which SQL statement displays the desired results?","o":["SELECT last_name, (salary * 12) * NVL(commission_pct, 0) FROM EMPLOYEES;","SELECT last_name, (salary * 12) * commission_pct FROM EMPLOYEES;","SELECT last_name, (salary * 12) * IFNULL(commission_pct,0) FROM EMPLOYEES;","SELECT last_name, (salary * 12) * NVL2(commission_pct, 0) FROM EMPLOYEES;"],"c":0,"qv":"","ov":[],"ex":""},{"id":115,"m":6,"q":"You would like to display the system date in the format \"Monday, 01 June, 2001\".\nWhich SELECT statement should you use?","o":["SELECT TO_CHAR(SYSDATE, 'FMDay, DD Month, YYYY') FROM dual;","SELECT TO_DATE(SYSDATE, 'FMDAY, DD Month, YYYY') FROM dual;","SELECT TO_CHAR(SYSDATE, 'FMDD, DY Month, 'YYY') FROM dual;","SELECT TO_CHAR(SYSDATE, 'FMDY, DDD Month, YYYY') FROM dual;"],"c":0,"qv":"","ov":[],"ex":""},{"id":116,"m":6,"q":"Evaluate the SQL statement:\nSELECT ROUND(TRUNC(MOD(1600, 10), -1), 2)\nFROM dual;\nWhat will be displayed?","o":["0","1","0.00","An error statement"],"c":0,"qv":"","ov":[],"ex":""},{"id":117,"m":6,"q":"Which SELECT statement will not display 2000 in the format '$2,000.00'","o":["SELECT TO_CHAR (2000, '$2,000.00') FROM dual;","SELECT TO_CHAR (2000, '$0,000.00') FROM dual;","SELECT TO_CHAR (2000, '$9,999.00') FROM dual;","SELECT TO_CHAR (2000, '$9,999.99') FROM dual;"],"c":0,"qv":"","ov":[],"ex":""},{"id":118,"m":6,"q":"Which statement is incorrect about functions that are available in SQL?","o":["NVL2 returns the first non-null expression in the expression list.","DECODE translates an expression after comparing it to each search value.","TRIM trims the heading of trailing characters (or both) from a character string.","NULLIF compares two expressions and returns null if they are equal, or the first expression if they are not equal"],"c":0,"qv":"","ov":[],"ex":""},{"id":119,"m":6,"q":"Which is a character manipulation function?","o":["TRIM","TRUNC","TO_DATE","MOD"],"c":0,"qv":"","ov":[],"ex":""},{"id":120,"m":6,"q":"Which task can you perform by using the TO_CHAR function?","o":["Convert '10' to '10'","Convert 10 to 'TEN'","Convert '10' to 10","Convert 'TEN' to 10"],"c":0,"qv":"","ov":[],"ex":""},{"id":121,"m":7,"q":"Which statement is true about WHERE and HAVING clauses?","o":["A HAVING clause can be used to restrict groups only.","A WHERE clause can be used to restrict groups only.","A WHERE clause can be used to restrict both rows and groups.","A HAVING clause can be used to restrict both rows and groups."],"c":3,"qv":"","ov":[],"ex":""},{"id":122,"m":7,"q":"Examine the description of the EMPLOYEES table:\nEMP_ID      NUMBER(4)     NOT NULL\nLAST_NAME   VARCHAR2(30)  NOT NULL\nFIRST_NAME  VARCHAR2(30)\nDEPT_ID     NUMBER(2)\nWhich statement produces the number of different departments that have employees with last name Smith?","o":["SELECT DISTINCT(COUNT(dept_id)) FROM employees WHERE last_name='Smith';","SELECT COUNT(*) FROM employees WHERE last_name='Smith';","SELECT COUNT(DISTINCT dept_id) FROM employees WHERE last_name='Smith';","SELECT COUNT (dept_id) FROM employees WHERE last_name='Smith';"],"c":2,"qv":"","ov":[],"ex":""},{"id":123,"m":7,"q":"What is true of using group functions on columns that contain NULL values?","o":["Group functions on columns returning dates include NULL values.","Group functions on columns ignore NULL values.","Group functions on columns cannot be accurately used on columns that contain NULL values.","Group functions on columns returning numbers include NULL values."],"c":1,"qv":"","ov":[],"ex":""},{"id":124,"m":7,"q":"The STUDENT_GRADES table has these columns:\nSTUDENT_ID    NUMBER(12)\nSEMESTER_END  DATE\nGPA           NUMBER(4,3)\nWhich statement finds the highest grade point average (GPA) per semester?","o":["SELECT MAX(gpa) FROM student_grades WHERE gpa IS NOT NULL GROUP BY semester_end;","SELECT (gpa) FROM student_grades GROUP BY semester_end WHERE gpa IS NOT NULL","SELECT MAX(gpa) FROM student_grades WHERE gpa IS NOT NULL","SELECT MAX(gpa) GROUP BY semester_end WHERE gpa IS NOT NULL FROM student_grades"],"c":0,"qv":"","ov":[],"ex":""},{"id":125,"m":7,"q":"Which of the following data types are compatible for applying the group functions such as MIN, MAX ?","o":["Numeric","Date","All of the above","Character"],"c":2,"qv":"","ov":[],"ex":""},{"id":126,"m":7,"q":"Which of the following is not a valid variation of the COUNT function ?","o":["COUNT(*)","COUNT(expr1, expr2)","COUNT(DISTINCT expr)","COUNT(expr)"],"c":1,"qv":"","ov":[],"ex":""},{"id":127,"m":7,"q":"Which of the following statements calculates the Average commission percentage from the employees table by treating the NULLs as zeros wherever the commission percentage is NULL ?","o":["SELECT AVG(NVL(commission_pct, 0)) FROM employees","SELECT NULLIF(AVG(commission_pct), 0) FROM employees","SELECT AVG(NULLIF(commission_pct, 0)) FROM employees","SELECT NVL(AVG(commission_pct), 0) FROM employees"],"c":0,"qv":"","ov":[],"ex":""},{"id":128,"m":7,"q":"Which of the following statements will return error?","o":["SELECT AVG(salary) FROM employees GROUP BY department_id","SELECT department_id, AVG(salary) FROM employees GROUP BY department_id","SELECT job_id, AVG(salary) FROM employees GROUP BY department_id","SELECT AVG(salary), job_id FROM employees GROUP BY department_id, job_id"],"c":2,"qv":"","ov":[],"ex":""},{"id":129,"m":7,"q":"Which of the following statements is not correct?","o":["You cannot use the WHERE clause to restrict groups","You can use group functions in the WHERE clause","You cannot use group functions in the WHERE clause","You use the HAVING clause to restrict groups"],"c":1,"qv":"","ov":[],"ex":""},{"id":130,"m":7,"q":"Which of the following statements displays the number of distinct department values in the EMPLOYEES table","o":["SELECT COUNT(department_id) FROM employees","SELECT DISTINCT COUNT(department_id) FROM employees","SELECT COUNT(DISTINCT department_id) FROM employees","SELECT DISTINCT department_id FROM employees;"],"c":2,"qv":"","ov":[],"ex":""},{"id":131,"m":7,"q":"What will be the output of the following statement?\nSELECT department_id, AVG(salary)\nFROM employees\nWHERE AVG(salary) > 8000\nGROUP BY department_id;","o":["The statement will display the list of department ids and average salary of the employees table where average","The statement will display a list of departments and average salary of each department","The statement will display a list departments and average salary of each department only for departments whose average salary is greater than 8000","The statement will return an error"],"c":3,"qv":"","ov":[],"ex":""},{"id":132,"m":7,"q":"Examine the description of the STUDENTS table:\nSTD_ID      NUMBER(4)\nCOURSE_ID   VARCHAR2(10)\nSTART_DATE  DATE\nEND_DATE    DATE\nWhich of the aggregate functions is valid on the START_DATE column?","o":["MIN(start_date)","AVG(start_date)","MAXIMUM(start_date)","SUM(start_date)"],"c":0,"qv":"","ov":[],"ex":""},{"id":133,"m":7,"q":"What is True about the below statement?\nSELECT MAX(AVG(salary))\nFROM employees\nGROUP BY department_id;","o":["It will return an error as Group functions can not be nested","It will return Maximum average salary for each department","It will return error because Salary is not included in the group by clause","It will display the maximum of the average salaries for each department"],"c":3,"qv":"","ov":[],"ex":""},{"id":134,"m":7,"q":"Examine the description of the MARKS table:\nSTD_ID        NUMBER(4)\nSTUDENT_NAME  VARCHAR2(30)\nSUBJ1         NUMBER(3)\nSUBJ2         NUMBER(3)\nSUBJ1 and SUBJ2 indicate the marks obtained by a student in two subjects. Examine this SELECT statement based on the MARKS table:\nSELECT subj1+subj2 total_marks, std_id\nFROM marks\nWHERE subj1 > AVG(subj1) AND subj2 > AVG(subj2)\nORDER BY total marks;\nWhat is the result of the SELECT statement?","o":["The statement returns an error at the WHERE clause.","The statement executes successfully and returns the student ID and sum of all marks for each student who obtained more than the average mark in each subject.","The statement returns an error at the SELECT clause.","The statement returns an error at the ORDER BY clause."],"c":0,"qv":"","ov":[],"ex":""},{"id":135,"m":9,"q":"Which statement is true about aggregate functions?","o":["You can mix single row columns with aggregate functions in the column list of a SELECT statement by grouping on the single row columns.","You can use aggregate functions only in the column list of the SELECT clause and in the WHERE clause of a SELECT statement.","You can use aggregate functions on a table, only by grouping the whole table as one single group.","You can use aggregate functions in any clause of a SELECT statement."],"c":0,"qv":"","ov":[],"ex":""},{"id":136,"m":7,"q":"Which clause should you use to exclude group results?","o":["HAVING","RESTRICT","WHERE","GROUP BY"],"c":0,"qv":"","ov":[],"ex":""},{"id":137,"m":7,"q":"In a SELECT statement that includes a WHERE clause, where should the GROUP BY clause placed?","o":["Before the WHERE clause","After the ORDER BY clause","Immediately after the SELECT clause","After the WHERE clause"],"c":3,"qv":"","ov":[],"ex":""},{"id":138,"m":7,"q":"The EVENT table contains these columns:\nEVENT_ID     NUMBER\nEVENT_NAME   VARCHAR2(30)\nEVENT_DESC   VARCHAR2(100)\nEVENT_TYPE   NUMBER\nLOCATION_ID  NUMBER\nYou have been asked to provide a report of the number of different event types at each location.\nWhich SELECT statement will produce the desired result?","o":["SELECT COUNT(*), DISTINCT(location_id) FROM event;","SELECT location_id, COUNT(DISTINCT event_type) FROM event GROUP BY location_id;","SELECT DISTINCT (event_type) FROM event GROUP BY location_id;","SELECT UNIQUE(location_id), COUNT(event_type) FROM event GROUP BY location_id;"],"c":1,"qv":"","ov":[],"ex":""},{"id":139,"m":7,"q":"Which statement about the evaluation of clauses in a SELECT statement is true?","o":["The Oracle Server will evaluate an ORDER BY clause before a WHERE clause.","The Oracle Server will evaluate a WHERE clause before a GROUP BY clause.","The Oracle Server will evaluate an ORDER BY clause before a HAVING clause.","The Oracle Server will evaluate a HAVING clause before a WHERE clause"],"c":1,"qv":"","ov":[],"ex":""},{"id":140,"m":7,"q":"You need to calculate the total of all salaries in the accounting department. Which group function should you use?","o":["COUNT","MAX","MIN","SUM"],"c":3,"qv":"","ov":[],"ex":""},{"id":141,"m":8,"q":"In which case would you use a FULL OUTER JOIN?","o":["You want all unmatched data from one table.","You want all unmatched data from both tables.","Both tables have NULL values.","You want all matched data from both tables."],"c":1,"qv":"","ov":[],"ex":""},{"id":142,"m":8,"q":"What will be the output of the following query?\nSELECT *\nFROM employees, departments;","o":["It will display rows from employees table followed by rows from departments table.","It will by default the join two tables on department_id because it is a referential integrity column.","It will result in a Cartesian product as a joining condition is not specified","It will return error as a join condition is not specified"],"c":2,"qv":"","ov":[],"ex":""},{"id":143,"m":8,"q":"Which of the following queries will produce identical output as the query below?\nSELECT last_name, department_name\nFROM employees\nCROSS JOIN departments;","o":["SELECT last_name, department_name FROM employees e, departments d WHERE e.depatment_id (+) = d.department_id (+);","SELECT last_name, department_name FROM employees JOIN departments USING (department_id)","SELECT last_name, department_name FROM employees e, departments d WHERE e.depatment_id = d.department_id;","SELECT last_name, department_name FROM employees e, departments d;"],"c":3,"qv":"","ov":[],"ex":""},{"id":144,"m":8,"q":"Which of the following is an outer join symbol?","o":["[+]","(+)","{+}","+"],"c":1,"qv":"","ov":[],"ex":""},{"id":145,"m":2,"q":"What will be the output of the following query?\nSELECT e.last_name, e.department_id, d.department_name\nFROM employees e, departments d\nWHERE e.department_id(+) = d.department_id;","o":["Displays employee last names, department ID's and department names for all employees irrespective of the matching department id present in departments table or not.","Displays employee last names, department ID's and department names for all employees.","Displays employee last names, department ID's for all employees and also the department names for all departments.","Displays employee last names, department ID's and department names for all employees and also the department names of departments who have no match in employees table."],"c":3,"qv":"","ov":[],"ex":""},{"id":146,"m":8,"q":"Which of the following type of join was not available in Oracle versions 8i and prior?","o":["Full Outer Join","Self Join","Left Outer Join","Right Outer Join"],"c":0,"qv":"","ov":[],"ex":""},{"id":147,"m":8,"q":"Which of the following statements about use of table aliases and prefixes in Join queries is not Valid ?","o":["We can simplify queries by using table aliases.","Table prefixes must be used to unambiguously identify the columns with same names.","We can improve performance by using table prefixes.","Table prefixes must be used when joining more than three tables."],"c":3,"qv":"","ov":[],"ex":""},{"id":148,"m":8,"q":"Which of the following statements indicate correct way of using a Natural Join?","o":["SELECT department_id, department_name, location_id, city FROM departments d NATURAL JOIN locations l using (l.location_id);","SELECT department_id, department_name, location_id, city FROM departments NATURAL JOIN locations on (location_id);","SELECT department_id, department_name, location_id, city FROM departments NATURAL JOIN locations;","SELECT department_id, department_name, location_id, city FROM departments d NATURAL JOIN locations l WHERE d.location_id = l.location_id"],"c":2,"qv":"","ov":[],"ex":""},{"id":149,"m":8,"q":"Which of the following statements is not true about joins?","o":["To specify arbitrary conditions or specify columns to join, the ON clause is used.","Natural join and using clause can be used together.","Use the USING clause to match only one column when more than one column matches.","If the columns having the same names have different data types, an error is returned in case of a Natural Join."],"c":1,"qv":"","ov":[],"ex":""},{"id":150,"m":8,"q":"Which SQL statement produces the name, department name, and the city of all the employees who earn more than 10000?","o":["SELECT emp_name, department_name, city FROM employees e, departments d, locations 1 JOIN ON (e.department_id = d.department id) AND (d.location_id =1.location_id) AND salary > 10000;","SELECT emp_name, department_name, city FROM employees e, departments d, locations 1 WHERE salary > 10000;","SELECT emp_name, department_name, city FROM employees e JOIN departments d USING (department_id) JOIN locations 1 USING (location_id) WHERE salary > 10000;","SELECT emp_name, department_name, city FROM employees e NATURAL JOIN departments, locations WHERE salary > 10000;"],"c":0,"qv":"","ov":[],"ex":""},{"id":151,"m":8,"q":"You want to retrieve all employees, whether or not they have matching departments in the departments table. Which query would you use?","o":["SELECT last_name, department_name FROM employees e LEFT OUTER JOIN departments d ON (e.department_id = d.department_id);","SELECT last_name, department_name FROM employees , departments(+);","SELECT last_name, department_name FROM employees JOIN departments (+);","SELECT last_name, department_name FROM employees e RIGHT OUTER JOIN departments d ON (e.department_id = d.department_id);"],"c":0,"qv":"","ov":[],"ex":""},{"id":152,"m":8,"q":"Which is not true regarding the use of outer joins?","o":["In the WHERE condition, you use (+) following the name of the column in the table without matching rows, to perform an outerjoin.","You use an outerjoin to see only the rows that do not meet the join condition.","You cannot link a condition that is involved in an outerjoin to another condition by using the OR operator.","You cannot an outer join while joining more than 2 tables"],"c":3,"qv":"","ov":[],"ex":""},{"id":153,"m":8,"q":"Which of the following joins is also called an Inner join?","o":["Self Join","Outer Join","Non-Equi Join","Equi Join"],"c":3,"qv":"","ov":[],"ex":""},{"id":154,"m":8,"q":"What is true about joining tables through an equijoin?","o":["You specify an equijoin condition in the SELECT or FROM clauses of a SELECT statement.","You can join n tables (all having single column primary keys) in a SQL statement by specifying a minimum of n-1 join conditions.","You can join a maximum of two columns through an equijoin.","You can join a maximum of two tables through an equijoin."],"c":1,"qv":"","ov":[],"ex":""},{"id":155,"m":8,"q":"Examine the structure of the EMPLOYEES, DEPARTMENTS, and TAX tables.\nEMPLOYEES\nEMPLOYEE_ID      NUMBER        NOT NULL, Primary Key\nEMP_NAME         VARCHAR2(30)\nJOB_ID           VARCHAR2(20)\nSALARY           NUMBER\nMGR_ID           NUMBER        References EMPLOYEE_ID column\nDEPARTMENT_ID    NUMBER        Foreign key to DEPARTMENT_ID column of the DEPARTMENTS table\nDEPARTMENTS\nDEPARTMENT_ID    NUMBER        NOT NULL, Primary Key\nDEPARTMENT_NAME  VARCHAR2(30)\nMGR_ID           NUMBER        References MGR_ID column of the EMPLOYEES table\nTAX\nMIN_SALARY       NUMBER\nMAX_SALARY       NUMBER\nTAX_PERCENT      NUMBER\nFor which situation would you use a non-equijoin query?","o":["To find the number of employees working for the Administrative department and earning less then 4000.","To find the tax percentage for each of the employees","To list the name, job id, and manager name for all the employees.","To find the name, salary, and department name of employees who are not working with Smith."],"c":1,"qv":"","ov":[],"ex":""},{"id":156,"m":8,"q":"To produce a meaningful result set without any cartesian products, what is the minimum number of conditions that should appear in the WHERE clause of a four-table join?","o":["2","4","3","8"],"c":2,"qv":"","ov":[],"ex":""},{"id":157,"m":8,"q":"In which case would you use an outer join?","o":["The tables being joined have NOT NULL columns.","The tables being joined have both matched and unmatched data.","The tables being joined have only unmatched data","The tables being joined have only matched data."],"c":1,"qv":"","ov":[],"ex":""},{"id":158,"m":8,"q":"When will a Cartesian product occur?","o":["All rows in the first table are joined to all rows in the second table","A join condition is omitted","A join condition is invalid","Two tables are joined on the columns having different names."],"c":3,"qv":"","ov":[],"ex":""},{"id":159,"m":8,"q":"Which of the following is not a valid type of Join?","o":["External Join","Outer Join","Inner Join","Natural join"],"c":0,"qv":"","ov":[],"ex":""},{"id":160,"m":8,"q":"Which type of join is used in the following query?\nSELECT e.employee_id, e.last_name, d.department_id, d.location_id\nFROM employees e, departments d\nWHERE e.department_id = d.department_id;","o":["Self Join","Non-equi Join","Equi join","Left Outer join"],"c":2,"qv":"","ov":[],"ex":""},{"id":161,"m":9,"q":"Evaluate this SELECT statement:\nSELECT employee_id, name\nFROM employee\nWHERE employee_id NOT IN (SELECT employee_id\n                          FROM employee\n                          WHERE department_id = 30\n                          AND job = 'CLERK');\nWhat would happen if the inner query returned a NULL value?","o":["A syntax error would be returned.","Only the rows with EMPLOYEE_ID values equal to NULL would be included in the results.","All the EMPLOYEE_ID and NAME values in the EMPLOYEE table would be displayed.","No rows would be selected from the EMPLOYEE table."],"c":3,"qv":"","ov":[],"ex":""},{"id":162,"m":9,"q":"In which clause a subquery cannot be used?","o":["in the FROM clause of a SELECT statement","in the GROUP BY clause of a SELECT statement","in the SET clause of an UPDATE statement","in the WHERE clause of a SELECT statement"],"c":1,"qv":"","ov":[],"ex":""},{"id":163,"m":11,"q":"Which best describes an inline view?","o":["a subquery that is part of the FROM clause of another query","a subquery that can contain an ORDER BY clause","another name for a view that contains group functions","a schema object"],"c":0,"qv":"","ov":[],"ex":""},{"id":164,"m":9,"q":"Which statement about subqueries is true?","o":["A subquery can retrieve zero or more rows.","A subquery should retrieve only one row","Subqueries CANOT be nested by more than two levels.","A subquery can be used only in SQL query statements."],"c":0,"qv":"","ov":[],"ex":""},{"id":165,"m":9,"q":"Which statement will display employees who have same job id as that of 'Hass' and earn more than 10000 ?","o":["SELECT last_name, job_id FROM employees WHERE job_id IN (SELECT job_id FROM employees WHERE last_name = 'Haas') AND salary > 10000;","SELECT last_name, job_id FROM employees WHERE last_name = 'Haas' AND salary >10000","SELECT last_name, job_id FROM employees WHERE job_id IN (SELECT job_id FROM employees WHERE Salary > 10000) AND last_name = 'Haas'","SELECT last_name, job_id FROM employees WHERE job_id = (SELECT job_id FROM employees WHERE last_name = 'Haas' AND salary > 10000);"],"c":0,"qv":"","ov":[],"ex":""},{"id":166,"m":9,"q":"__________ is used to retrieve data from one or more tables if there is no relation between the tables.","o":["Sub query","Both","Joins","None of the above"],"c":0,"qv":"","ov":[],"ex":""},{"id":167,"m":9,"q":"A subquery can be used to _________.","o":["Retrieve data based on an unknown condition","Create groups of data","Convert data to a different format","Sort data in a specific order"],"c":0,"qv":"","ov":[],"ex":""},{"id":168,"m":9,"q":"Examine the data in the EMPLOYEES table:\nLAST_NAME  DEPARTMENT_ID  SALARY\n---------  -------------  ------\nGetz       10             3000\nDavis      20             1500\nKing       20             2200\nDavis      30             5000\nWhich of these sub queries will not work?","o":["SELECT distinct department_id FROM employees Where salary > ANY (SELECT AVG(salary) FROM employees GROUP BY department_id)","SELECT last_name FROM employees Where salary > ANY (SELECT MAX(salary) FROM employees GROUP BY department_id)","SELECT * FROM employees where salary > (SELECT MIN(salary) FROM employees GROUP BY department.id)","SELECT department_id FROM employees WHERE SALARY > ALL (SELECT AVG(salary) FROM employees GROUP BY department_id)"],"c":2,"qv":"","ov":[],"ex":""},{"id":169,"m":12,"q":"What is the use of LEVEL pseudocolumn?","o":["It is used to indicate the starting node of the hierarchical query","It is used to display the level of a row in the hierarchy","None of the above","It is used to level the output of the query"],"c":1,"qv":"","ov":[],"ex":""},{"id":170,"m":2,"q":"Which query will display the details of the employees and their manager in a TOP-DOWN tree structure, starting with employee 'King'?","o":["SELECT employee_id, last_name, job_id, manager_id FROM employees START WITH last_name = 'King' CONNECT BY PRIOR employee_id = manager_id ;","SELECT employee _id, last_name, job_id, manager_id FROM employees START WITH last_name = 'King' CONNECT BY PRIOR manager_id = employee_id;","SELECT employee_id, last_name, job_id, manager_id FROM employees START WITH last_name = 'King' CONNECT BY PRIOR employee_id TOP_DOWN;","D. SELECT employee_id, last_name, job_id, manager_id FROM employeesSTART WITH last_name = 'King' CONNECT BY TOP_DOWN employee_id = manager_id ;"],"c":0,"qv":"","ov":[],"ex":""},{"id":171,"m":2,"q":"What will be the output of the below query?\nSELECT last_name, job_id, salary\nFROM employees\nWHERE job_id = (SELECT job_id FROM employees WHERE employee_id = 141)\nAND salary > (SELECT salary FROM employees WHERE employee_id = 143);","o":["Display employees whose job ID is the same as that of employee 141 or 143 and whose salary is greater than that of employee 141 or 143.","Display employees whose job ID is the same as that of employee 141 and 143 and whose salary is greater than that of employee 141 and 143.","Display employees whose job ID is the same as that of employee 141 or whose salary is greater than that of employee 143.","Display employees whose job ID is the same as that of employee 141 and whose salary is greater than that of employee 143."],"c":3,"qv":"","ov":[],"ex":""},{"id":172,"m":9,"q":"Which statement regarding subqueries is true?","o":["A subquery CANNOT reference a table that is not included in the outer query's FROM clause.","A subquery must be placed on the right side of the comparison operator.","Subqueries can return multiple columns.","Subqueries cannot be nested up to3 levels."],"c":2,"qv":"","ov":[],"ex":""},{"id":173,"m":9,"q":"Which of the following is not a multiple-row comparison operator?","o":["ANY","IN","EACH","ALL"],"c":2,"qv":"","ov":[],"ex":""},{"id":174,"m":9,"q":"Evaluate this SQL statement:\nSELECT product_id, product_name, price\nFROM product\nWHERE supplier_id IN (SELECT supplier_id\n                      FROM product\n                      WHERE price > 120\n                      OR qty_in_stock > 100);\nWhich values will be displayed?","o":["The PRODUCT_ID , PRODUCT_NAME, and PRICE of products that are priced greater than $120.00 or that has a QTY_IN_STOCK value greater than 100","The PRODUCT_ID, PRODUCT_NAME, and PRICE of products that are priced greater than $120.00 and have a QTY_IN_STOCK value greater than 100","The PRODUCT_ID, PRODUCT_NAME, and PRICE of products supplied by a supplier with products that are priced greater than $120.00 or with products that have a QTY_IN_STOCK value greater than 100","The PRODUCT_ID, PRODUCT_NAME, and PRICE of products that are priced greater than $120.00 or that has a QTY_IN_STOCK value less than 100"],"c":2,"qv":"","ov":[],"ex":""},{"id":175,"m":9,"q":"A subquery can be used to _________.","o":["Sort data in a specific order","Create groups of data.","Retrieve data based on an unknown condition","Convert data to a different format"],"c":2,"qv":"","ov":[],"ex":""},{"id":176,"m":9,"q":"Which statement about subqueries is not true?","o":["A single row subquery can retrieve only one column and one row.","A multiple row subquery can retrieve multiple rows and multiple columns.","A multiple row subquery can be compared by using the \">\" operator.","A single row subquery can retrieve only one row but many columns."],"c":0,"qv":"","ov":[],"ex":""},{"id":177,"m":9,"q":"You define a multiple-row subquery in the WHERE clause of an SQL query with a comparison operator \"=\". What happens when the main query is executed?","o":["The main query fails because the multiple-row subquery cannot be used with the comparison operator.","The main query executes with the last value returned by the subquery.","The main query executes with all the values returned by the subquery.","The main query executes with the first value returned by the subquery."],"c":0,"qv":"","ov":[],"ex":""},{"id":178,"m":9,"q":"Which operator can be used with a multiple-row subquery?","o":["LIKE","=","NOT IN","BETWEEN"],"c":2,"qv":"","ov":[],"ex":""},{"id":179,"m":9,"q":"Which statement about subqueries is true?","o":["A single row subquery can retrieve data from only one table","A single row subquery cannot be used in a condition where the LIKE operator is used for comparison.","A SQL query statement cannot display data from table B that is referred to in its","A SQL query statement can display data from table B that is referred to in its subquery, without including table B in its own FROM clause."],"c":2,"qv":"","ov":[],"ex":""},{"id":180,"m":9,"q":"Examine the structure of the EMPLOYEES and NEW_EMPLOYEES tables:\nEMPLOYEES\nEMPLOYEE_ID  NUMBER        Primary Key\nFIRST_NAME   VARCHAR2(25)\nLAST_NAME    VARCHAR2(25)\nHIRE_DATE    DATE\nNEW_EMPLOYEES\nEMPLOYEE_ID  NUMBER        Primary Key\nNAME         VARCHAR2(60)\nWhich DELETE statement is valid?","o":["DELETE FROM employees WHERE employee_id IN (SELECT employee_id FROM new_employees WHERE name = 'Carrey');","DELETE FROM employees WHERE employee_id = (SELECT employee_id FROM employees);","DELETE * FROM employees WHERE employee_id IN (SELECT employee_id FROM new_employees WHERE last_name = 'Carrey');","DELETE * FROM employees WHERE employee_id = (SELECT employee_id FROM new_employees);"],"c":0,"qv":"","ov":[],"ex":""},{"id":181,"m":10,"q":"Which statement about the Sub queries is not valid?","o":["The subquery (inner query) returns a value that is used by the parent statement","A subquery is a SELECT statement that is embedded in a clause of another SQL statement","Using a nested subquery is equivalent to performing two sequential queries and using the result of the inner query as the search value in the outer query","The Outer query is executed first and then the inner subquery."],"c":3,"qv":"","ov":[],"ex":""},{"id":182,"m":10,"q":"Which type of sub query is used in the following SQL statement?\nSELECT employee_id, last_name,\n       (CASE\n          WHEN department_id = (SELECT department_id FROM departments\n                                WHERE location_id = 1800)\n          THEN 'Canada' ELSE 'USA'\n        END) location\nFROM employees;","o":["Pair-wise comparison sub-query","Correlated sub query","Inline sub query","Scalar Sub query"],"c":3,"qv":"","ov":[],"ex":""},{"id":183,"m":10,"q":"Which statement is not true about the Correlated sub Queries?","o":["A correlated sub query is evaluated once for each row processed by the parent statement.","The parent statement can be a SELECT, UPDATE, or DELETE statement.","A correlated sub query is evaluated once for each parent statement.","The Oracle Server performs a correlated sub query when the sub query references a column from a table referred to in the parent statement."],"c":2,"qv":"","ov":[],"ex":""},{"id":184,"m":10,"q":"Which type of sub query is used in the following SQL statement?\nSELECT employee_id, last_name\nFROM employees e\nORDER BY (SELECT department_name\n          FROM departments d\n          WHERE e.department_id = d.department_id);","o":["Pair-wise comparison sub-query","Correlated sub query","nline sub query","Non-pair wise comparison query"],"c":1,"qv":"","ov":[],"ex":""},{"id":185,"m":10,"q":"What does EXISTS operator return when the inner query selects no records?\nA. NULL\nB. 0\nC. FALSE\nD. TRUE","o":["0","FALSE","TRUE","NULL"],"c":1,"qv":"","ov":[],"ex":""},{"id":186,"m":10,"q":"What will be the output of the following query?\nSELECT employee_id, last_name, job_id, department_id\nFROM employees outer\nWHERE EXISTS (SELECT 'X'\n              FROM employees\n              WHERE manager_id = outer.employee_id);","o":["Display employees who have at least one person reporting to them with employee_id as 'X'","Display employees who have at least one person reporting to them.","Display employees who have at least one manager assigned to them.","Display employees who have at least one person reporting to them with name 'X'"],"c":1,"qv":"","ov":[],"ex":""},{"id":187,"m":10,"q":"Which of the following queries displays all departments that do not have any employees?","o":["SELECT department_id, department_name FROM departments d WHERE NOT EXISTS (SELECT 'X' FROM employees WHERE department_id = d.department_id);","SELECT department_id, department_name FROM departments d WHERE EXISTS (SELECT 'X' FROM employees WHERE department_id = d.department_id);","SELECT department_id, department_name FROM departments d WHERE NOT EXISTS (SELECT 'X' FROM employees WHERE department_id = department_id);","SELECT department_id, department_name FROM departments d WHERE EXISTS (SELECT 'X' FROM employees WHERE department_id = department_id);"],"c":0,"qv":"","ov":[],"ex":""},{"id":188,"m":10,"q":"Examine the Update statement below, which type of update is this?\nUPDATE employees e\nSET department_name = (SELECT department_name\n                       FROM departments d\n                       WHERE e.department_id = d.department_id);","o":["Inline Update","Correlated Update","Direct Update","Indirect Update"],"c":1,"qv":"","ov":[],"ex":""},{"id":189,"m":10,"q":"Which of the following is a correlated sub query to delete only those rows from the EMPLOYEES table that also exist in the EMP_HISTORY table?","o":["DELETE FROM employees E WHERE employee_id IN (SELECT employee_id FROM employees E, emp_history H WHERE E.employee_id = H. employee_id; );","DELETE FROM employees E WHERE employee_id = (SELECT employee_id FROM emp_history WHERE employee_id = E.employee_id);","DELETE FROM employees E WHERE employee_id IN (SELECT employee_id FROM emp_history H)","DELETE FROM employees E , emp_history H WHERE E.employee_id = H. employee_id;"],"c":1,"qv":"","ov":[],"ex":""},{"id":190,"m":11,"q":"Which of the following is not true about using the WITH clause?","o":["Using the WITH clause, you can define a query block before using it in a query.","The WITH clause is also known as subquery_factoring_clause.","The WITH clause enables you to reuse the same query block in a SELECT statement when it occurs more than once within a complex query","The WITH clause, unlike the Inline views, can create permanent and reusable views"],"c":3,"qv":"","ov":[],"ex":""},{"id":191,"m":10,"q":"When should the use of WITH clause be more effective?","o":["WITH clause is used when the query has many number of tables to be joined.","When using the Inline sub queries in the FROM clause.","When a query has many references to the same query block and there are joins and aggregations.","WITH clause can be used to replace the correlated sub queries for faster performance"],"c":2,"qv":"","ov":[],"ex":""},{"id":192,"m":10,"q":"Which of the following is a valid usage of a sub-query?","o":["To define the set of rows to be inserted into the target table of an INSERT or CREATE TABLE statement","To provide values for conditions in WHERE, HAVING, and START WITH clauses of SELECT statements","All of the above","To define one or more values to be assigned to existing rows in an UPDATE statement"],"c":2,"qv":"","ov":[],"ex":""},{"id":193,"m":10,"q":"Which of the following is not a benefit of using the WITH Clause?","o":["It automatically sorts the output of the query","It evaluates a clause only once, even if it appears multiple times in the query.","It can enhance performance of the queries","It makes the query easy to read"],"c":0,"qv":"","ov":[],"ex":""},{"id":194,"m":9,"q":"Identify the odd one among the following operators used along with Sub-queries.","o":["=","ANY","ALL","IN"],"c":0,"qv":"","ov":[],"ex":""},{"id":195,"m":9,"q":"Which query will display the details of all employees who earn less than the average salary in the company?","o":["SELECT last_name, job_id, salary FROM employees WHERE salary < (SELECT AVG(salary) FROM employees GROUP BY Department_id);","SELECT last_name, job_id, salary FROM employees HAVING salary < (SELECT AVG(salary) FROM employees);","SELECT last_name, job_id, salary FROM employees WHERE salary ANY (SELECT AVG(salary) FROM employees GROUP BY department_id);","SELECT last_name, job_id, salary FROM employees WHERE salary < (SELECT AVG(salary) FROM employees);"],"c":3,"qv":"","ov":[],"ex":""},{"id":196,"m":9,"q":"What is a multicolumn sub query?","o":["There is no sub query as Multi-column sub query, there is only multi-row sub query","A sub query which selects more than one column is called a multi-column sub query","A multi-column sub query is the one that uses single-row operators for comparison","A sub query which uses decode statements to process multiple columns is called a multi-column sub query"],"c":1,"qv":"","ov":[],"ex":""},{"id":197,"m":9,"q":"What will be the output of the following multi-column sub query?\nSELECT employee_id, manager_id, department_id\nFROM employees\nWHERE (manager_id, department_id) IN\n      (SELECT manager_id, department_id\n       FROM employees\n       WHERE employee_id IN (178, 174));","o":["Display the details of the employees who are managed by the same manager and work in the same department as the employees with EMPLOYEE_ID 178 or 174.","Display the details of the employees who are managed by the same manager and work in the same department as the employees with EMPLOYEE_ID 178 and 174.","Display the details of the employees managed by the same manager as that of the employees with EMPLOYEE_ID 178 or 174 and work in the same department as the employees with EMPLOYEE_ID 178 or 174.","This statement will return Error"],"c":0,"qv":"","ov":[],"ex":""},{"id":198,"m":9,"q":"What will be the output of the following multi-column sub query?\nSELECT employee_id, manager_id, department_id\nFROM employees\nWHERE manager_id IN\n      (SELECT manager_id\n       FROM employees\n       WHERE employee_id IN (174, 141))\nAND department_id IN\n      (SELECT department_id\n       FROM employees\n       WHERE employee_id IN (174, 141))\nAND employee_id NOT IN (174, 141);","o":["Display the details of the employees who are managed by the same manager and work in the same department as the employees with EMPLOYEE_ID 178 or 174.","This statement will return Error","Display the details of the employees who are managed by the same manager and work in the same department as the employees with EMPLOYEE_ID 178 and 174.","Display the details of the employees managed by the same manager as that of the employees with EMPLOYEE_ID 178 or 174 and work in the same department as the employees with EMPLOYEE_ID 178 or 174."],"c":3,"qv":"","ov":[],"ex":""},{"id":199,"m":11,"q":"What is not true about the Inline Sub Queries?","o":["A sub query in the FROM clause of a SELECT statement defines a data source for that particular SELECT statement, and only that SELECT statement.","A sub query in the FROM clause of a SELECT statement is also called an inline view.","The inline views created during the Sub query can be used later by same or other queries.","You can use a sub query in the FROM clause of a SELECT statement, which is very similar to how views are used."],"c":2,"qv":"","ov":[],"ex":""},{"id":200,"m":9,"q":"Which of the following is not true about the Scalar sub queries?","o":["Multiple-column sub queries written to compare two or more columns, using a compound WHERE clause and logical operators, do not qualify as scalar sub queries","The value of the scalar sub query expression is the value of the select list item of the sub query.","If the sub query returns 0 rows, the value of the scalar sub query expression is NULL.","A sub query that returns exactly one column value from one row is also referred to as a scalar sub query."],"c":0,"qv":"","ov":[],"ex":""},{"id":201,"m":10,"q":"In which scenario would TOP N analysis be the best solution?","o":["You want to identify the person who makes the highest salary for all employees","You want to find the manager supervising the largest number of employees.","You want to rank the top three sales representatives who have sold the maximum number of products","You want to identify the most senior employee in the company"],"c":2,"qv":"","ov":[],"ex":""},{"id":202,"m":11,"q":"Examine the structure of the EMP_DEPT_VU view:\nColumn Name    Type          Remarks\n-------------  ------------  ---------------------------\nEMPLOYEE_ID    NUMBER        From the EMPLOYEES table\nEMP_NAME       VARCHAR2(30)  From the EMPLOYEES table\nJOB_ID         VARCHAR2(20)  From the EMPLOYEES table\nSALARY         NUMBER        From the EMPLOYEES table\nDEPARTMENT_ID  NUMBER        From the DEPARTMENTS table\nDEPT_NAME      VARCHAR2(30)  From the DEPARTMENTS table\nWhich of the following SQL statement produces an error?","o":["SELECT * FROM emp_dept_vu;","SELECT department_id, SUM(salary) FROM emp_dept_vu GROUP BY department_id;","SELECT department_id, job_id, AVG(salary) FROM emp_dept_vu GROUP BY department_id, job_id;","None of the statements produce an error; all are valid"],"c":3,"qv":"","ov":[],"ex":""},{"id":203,"m":11,"q":"Which SQL statement would you use to remove a view called EMP_DEPT_VU from your schema?","o":["REMOVE emp_dept_vu;","DELETE emp_dept_vu;","DROP emp_dept_vu","DROP VIEW emp_dept_vu"],"c":3,"qv":"","ov":[],"ex":""},{"id":204,"m":11,"q":"Top N analysis requires:","o":["Only an inline view","The use of ROWNUM pseudo column","The use of ROWID","a GROUP BY clause"],"c":1,"qv":"","ov":[],"ex":""},{"id":205,"m":11,"q":"What is true about updates through a view?","o":["When you update a view the constraints on the views always override the constraints on theunderlying tables","When you update a view group functions are automatically computed","You cannot update a view with group functions","When you update a view only the data in the view will be updated and not the table data"],"c":2,"qv":"","ov":[],"ex":""},{"id":206,"m":11,"q":"What does the FORCE option do for creating a view?","o":["creates a view regardless of whether or not the base tables exist","creates a view in another schema even if you don't have privileges","creates a view even if the underlying parent table has constraints","creates a view with constraints"],"c":0,"qv":"","ov":[],"ex":""},{"id":207,"m":11,"q":"Which of the following best describes an inline view?","o":["a schema object","a sub query that is part of the FROM clause of another query","a sub query that can contain an ORDER BY clause","another name for a view that contains group functions"],"c":1,"qv":"","ov":[],"ex":""},{"id":208,"m":11,"q":"Which statement about views is not true?","o":["A view can be created as read only","The table must exist to create a view on it","A view can be created with a GROUP BY clause in the SELECT statement.","A view can be created based on another view"],"c":1,"qv":"","ov":[],"ex":""},{"id":209,"m":7,"q":"Evaluate this SQL statement:\nSELECT a.emp_name, a.sal, a.dept_id, b.maxsal\nFROM employees a,\n     (SELECT dept_id, MAX(sal) maxsal\n      FROM employees\n      GROUP BY dept_id) b\nWHERE a.dept_id = b.dept_id\nAND a.sal < b.maxsal;\nWhat is the result of the statement?","o":["The statement produces an error at line 3","The statement produces an error at line 4","The statement returns the employee name, salary, department ID, and maximum salary earned in the department of the employee for all employees who earn less than the maximum salary in their department","The statement produces an error at line 1"],"c":2,"qv":"","ov":[],"ex":""},{"id":210,"m":11,"q":"You need to create a view called EMP_VU that allows the user to insert rows through the view. Which of the following SQL statement, when used to create the EMP_VU view, allows the user to insert rows?","o":["CREATE VIEW emp_Vu AS SELECT department_id, SUM(sal) TOTALSAL FROM employees WHERE mgr_id IN (102, 120) GROUP BY department_id;","CREATE VIEW emp_Vu AS SELECT employee_id, emp_name,department_id FROM employees WHERE mgr_id IN (102, 120);","CREATE VIEW emp_Vu AS SELECT employee_id, emp_name, job_id,DISTINCT department_id FROM employees;","CREATE VIEW emp_Vu AS SELECT employee_id, emp_name, job_iddepartment_id FROM employees WHERE mgr_id IN (102, 120);"],"c":3,"qv":"","ov":[],"ex":""},{"id":211,"m":11,"q":"You need to perform certain data manipulation operations through a view called EMP_DEPT_VU, which you previously created. You want to look at the definition of the view (the SELECT statement on which the view was created).\nHow do you obtain the definition of the view?","o":["Query the USER_VIEWS data dictionary view to search for the EMP_DEPT_VU view","Use the DESCRIBE VIEW command on the EMP_DEPT VU view","Use the DEFINE VIEW command on the EMP_DEPT VU view","Query the USER_SOURCE data dictionary view to search for the EMP_DEPT_VU view"],"c":0,"qv":"","ov":[],"ex":""},{"id":212,"m":11,"q":"What is necessary for your query on an existing view to execute successfully?","o":["The underlying tables must be in the same schema","The underlying tables must have data.","You need SELECT privileges only on the underlying tables","You need SELECT privileges on the view."],"c":3,"qv":"","ov":[],"ex":""},{"id":213,"m":11,"q":"When you use SQL Subquery in ________ clause of the select statement it is called inline view","o":["group by","order by","where","from"],"c":3,"qv":"","ov":[],"ex":""},{"id":214,"m":11,"q":"You created a view called EMP_DEPT_VU that contains three columns from the EMPLOYEES and DEPARTMENTS tables: EMPLOYEE_ID, EMPLOYEE_NAME and DEPARTMENT_NAME.\nThe DEPARTMENT_ID column of the EMPLOYEES table is the foreign key to the primary key DEPARTMENT_ID column of the DEPARTMENTS table.\nYou want to modify the view by adding a fourth column, MANAGER_ID of NUMBER data type from the EMPLOYEES tables.\nHow can you accomplish this task?","o":["ALTER VIEW emp_dept_vu AS SELECT employee_id, employee_name,department_name, manager_id FROM employee e, departments d WHERE e.department_id = d.department_id;","MODIFY VIEW emp_dept_vu (ADD manager_id NUMBER);","ALTER VIEW emp_dept_vu (ADD manager_id NUMBER);","CREATE OR REPLACE VIEW emp_dept_vu AS SELECT employee_id, employee_name,department_name, manager_id FROM employees e, departments d WHERE e.department_id = d.department_id;"],"c":3,"qv":"","ov":[],"ex":""},{"id":215,"m":11,"q":"Which statements concerning the creation of a view are true? (Choose all that apply.)","o":["View columns that are the result of derived values are named by Oracle.","When the view already exists, using the OR REPLACE option requires the re-granting of the object privileges previously granted on the view","A constraint name must be provided when using the WITH CHECK OPTION clause or theStatement will fail","A view can have column names that are different than the actual base table(s) column names by using column aliases."],"c":3,"qv":"","ov":[],"ex":""},{"id":216,"m":11,"q":"You are granted the CREATE VIEW privilege. What does this allow you to do?","o":["Create a table view","Create a view in any schema","Create a view in your schema","Create a sequence view in any schema"],"c":2,"qv":"","ov":[],"ex":""},{"id":217,"m":11,"q":"Which of the following is a valid option while creating a view?","o":["WITH BREAK OPTION","ON DELETE CASCADE","WITH GRANT OPTION","WITH CHECK OPTION"],"c":3,"qv":"","ov":[],"ex":""},{"id":218,"m":11,"q":"An inline view is a SELECT statement that is given an alias and is embedded in the ______ clause of another SELECT statement.","o":["CASE","FROM","WHERE","SELECT"],"c":1,"qv":"","ov":[],"ex":""},{"id":219,"m":11,"q":"You need to create a view EMP_VU. The view should allow the users to manipulate the records of only the employees that are working for departments 10 or 20.\nWhich SQL statement would you use to create the view EMP_VU?","o":["CREATE VIEW emp_vu AS SELECT * FROM employees WHERE department_id IN (10,20) WITH READ ONLY;","CREATE VIEW emp_vu AS SELECT * FROM employees WHERE department_id IN (10,20) WITH CHECK OPTION;","CREATE VIEW emp_vu AS SELECT * FROM employees WHERE department_id IN (10,20);","CREATE FORCE VIEW emp_vu AS SELECT * FROM employees WHERE department_id IN (10,20);"],"c":1,"qv":"","ov":[],"ex":""},{"id":220,"m":11,"q":"Which statement about views is true?","o":["A view cannot have an ORDER BY clause in the SELECT statement","A view cannot be created with a GROUP BY clause in the SELECT statement.","A view can be created as read only","A view must have aliases defined for the column names in the SELECT statement"],"c":2,"qv":"","ov":[],"ex":""},{"id":221,"m":12,"q":"Which of the following is not a SET operator?","o":["Intersect","Union","Minus","Plus"],"c":3,"qv":"","ov":[],"ex":""},{"id":222,"m":12,"q":"If the JOB_HISTORY table contains the records for those employees who have changed their jobs at least once, and you want to display the employee IDs of those employees who have not changed their jobs even once, which set operator should you use to write a query?","o":["Intersect","Minus","Union","Union All"],"c":1,"qv":"","ov":[],"ex":""},{"id":223,"m":12,"q":"Which of the following is not true about the use of Set operators in general?","o":["SET operators cannot be used in sub queries","The expressions in the SELECT lists must match in number and data type.","Parentheses can be used to alter the sequence of execution.","Queries that use UNION, UNION ALL, INTERSECT, and MINUS SET operators in their WHERE clause must have the same number and type of columns in their SELECT list"],"c":0,"qv":"","ov":[],"ex":""},{"id":224,"m":12,"q":"Which statement about the use of ORDER BY clause in conjunction with the SET Operators is not correct?","o":["The column name or alias, if used in an ORDER BY clause, must be from the first SELECT list.","The ORDER BY clause: Can accept the column name, an alias, or the positional notation","The ORDER BY clause: Can appear only at the very end of the statement","The ORDER BY clause: Can appear only at the end of the first SELECT statement"],"c":3,"qv":"","ov":[],"ex":""},{"id":225,"m":12,"q":"Which statement about the Oracle Server and SET Operators is not true?","o":["By default, the output is sorted in ascending order of the first column of the SELECT clause.","The column names in the output are decided by the column list in the first SELECT statement","The data types of the output columns are same as the selected columns","the Oracle Server eliminates duplicate rows automatically except in the case of the UNION ALL operator"],"c":2,"qv":"","ov":[],"ex":""},{"id":226,"m":9,"q":"What data does the DUAL table contain by default?","o":["One column named DUMMY and one row with value X","One column named D and one row with value X","One column named COL and one row with value 1","DUAL table doesn't contain any data by default."],"c":0,"qv":"","ov":[],"ex":""},{"id":227,"m":12,"q":"What is not true about the Oracle Pseudo columns?","o":["A pseudo column behaves like a table column, but is not actually stored in the table.","Pseudo columns are internally maintained by the Oracle server.","You cannot insert value of a pseudo column in other table's columns.","You can select from pseudo columns, but you cannot insert, update, or delete their values."],"c":2,"qv":"","ov":[],"ex":""},{"id":228,"m":12,"q":"Which of the following is not a valid type or name of an Oracle Pseudo-column?","o":["Hierarchical Query Pseudo columns","Sequence Pseudo columns","Sub Query Pseudo columns","ROWNUM Pseudo column"],"c":2,"qv":"","ov":[],"ex":""},{"id":229,"m":12,"q":"Which of the following statement, about sequence pseudo columns is true?","o":["You use a CURRVAL pseudo column to generate a value from a sequence that would be used for a specified database column.","You use a NEXTVAL pseudo column to look at the next possible value that would be generated from a sequence, without actually retrieving the value.","You use a CURRVAL pseudo column to generated next value of the sequence to be used.","You use a NEXTVAL pseudo column to obtain the next possible value from a sequence by actually retrieving the value from the sequence."],"c":3,"qv":"","ov":[],"ex":""},{"id":230,"m":12,"q":"Which of the following is not part of the information contained inside the ROWID pseudo column?","o":["The data object number of the object","The data file in which the row resides","The position of the row in the oracle table","The data block in the data file in which the row resides"],"c":2,"qv":"","ov":[],"ex":""},{"id":231,"m":12,"q":"Which of these pseudo columns is useful while performing the TOP-N analysis?","o":["RANK","ROWID","LEVEL","ROWNUM"],"c":3,"qv":"","ov":[],"ex":""},{"id":232,"m":12,"q":"If you want to select employees details from two different tables which may contain records for same employee ids, but want to display each employees record only once, which set operator should you use?","o":["Union","Union all","Minus","Intersect"],"c":0,"qv":"","ov":[],"ex":""},{"id":233,"m":12,"q":"What will be the output of the below query?\nSELECT *\nFROM employees\nWHERE ROWNUM < 10;","o":["This Query will perform TOP-N analysis to display TOP nine earning employees as ROWNUM is used.","This query will return error as ROWNUM is not used in the SELECT clause and only in the WHERE clause","The query will select only 10 records from employees table","This query will return 9 rows from the Employees table, if there are 9 or more records in the employees table"],"c":3,"qv":"","ov":[],"ex":""},{"id":234,"m":12,"q":"Queries containing SET operators are called _______ queries.","o":["Compound","Set","Complex","Set Manipulation"],"c":0,"qv":"","ov":[],"ex":""},{"id":235,"m":12,"q":"What is not true about the Union operator?","o":["UNION operates over all of the columns being selected.","The IN operator has a higher precedence than the UNION operator.","By default, the output is sorted in ascending order of the first column of the SELECT clause.","NULL values are ignored during duplicate checking."],"c":3,"qv":"","ov":[],"ex":""},{"id":236,"m":12,"q":"Which of the set operators when used, the output of the query is not sorted by default?","o":["Minus","Intersect","Union","Union All"],"c":3,"qv":"","ov":[],"ex":""},{"id":237,"m":12,"q":"Which of the following statement is not true about the UNION ALL operator?","o":["The DISTINCT keyword can be used","The output is not sorted by default","The UNION ALL operator to return all rows from multiple queries.","duplicate rows are not eliminated"],"c":0,"qv":"","ov":[],"ex":""},{"id":238,"m":12,"q":"What is not true about the use of Intersect operator?","o":["INTERSECT does not ignore NULL values.","The names of the columns need not be identical","The number of columns and the data types of the columns being selected by the SELECT statements in the queries must be identical in all the SELECT statements used in the query","Reversing the order of the intersected tables may result in a changed output"],"c":3,"qv":"","ov":[],"ex":""},{"id":239,"m":12,"q":"Which operator should you use to display the records which are a common result of each of the queries?","o":["Union","Minus","Intersect","Union All"],"c":2,"qv":"","ov":[],"ex":""},{"id":240,"m":12,"q":"Which of the following is correct about the use of Union operator?","o":["The data types of the columns being selected must be identical but the number of columns may be different.","The number of columns and the data types of the columns being selected must be identical in all the SELECT statements used in the query","The names of the columns must also be identical","The number of columns being selected must be identical but the data types of the columns may be different."],"c":1,"qv":"","ov":[],"ex":""},{"id":241,"m":13,"q":"Which the following statement is not true about Database Normalization ?","o":["Normalization usually involves combining small tables and consolidating them into a single table so that maximum data can be accessed through each table.","In the design of a relational database management system, the process of organizing data to minimize redundancy is called 'Normalization'.","The goal of database normalization is to decompose relations with anomalies in order to produce smaller, well-structured relations.","Normalization usually involves dividing large tables into smaller (and less redundant) tables and defining relationships between them."],"c":0,"qv":"","ov":[],"ex":""},{"id":242,"m":9,"q":"An attribute is fully functionally dependent on a set of attributes X if it is _________.","o":["Functionally dependent on X","Not functionally dependent on any proper subset of X.","Either A or B but not both","Both A and B"],"c":3,"qv":"","ov":[],"ex":""},{"id":243,"m":13,"q":"What is true about the Multivalued dependency?","o":["A multivalued dependency is a constraint according to which the presence of primary key in a table implies the presence of foreign keys.","A multivalued dependency is a constraint according to which the presence of certain rows in a table implies the presence of certain other rows.","A multivalued dependency is a constraint according to which the presence of functional dependency implies the presence of transitive dependency.","A multivalued dependency is a constraint according to which the presence of transitive dependency implies the presence of functional dependency."],"c":1,"qv":"","ov":[],"ex":""},{"id":244,"m":4,"q":"Which statement is true about the Super Keys?","o":["A super key cannot be a candidate key.","A table can have only one super key.","Super key may not contain all the columns present in the Candidate key of a table.","A super key is a combination of attributes that can be used to uniquely identify a database record"],"c":3,"qv":"","ov":[],"ex":""},{"id":245,"m":9,"q":"Which of the following statements is not true?","o":["A prime attribute is also part of all super keys of a table.","A prime attribute is an attribute that does occur in any candidate key.","A non-prime attribute is an attribute that does not occur in any super key.","A non-prime attribute is an attribute that does not occur in any candidate key."],"c":2,"qv":"","ov":[],"ex":""},{"id":246,"m":13,"q":"Which of the following conditions is not a valid condition for a table to be in First Normal Form (1NF)?","o":["There are no duplicate rows.","There's no top-to-bottom ordering to the rows.","There's left-to-right ordering to the columns.","Every row-and-column intersection contains exactly one value from the applicable domain"],"c":2,"qv":"","ov":[],"ex":""},{"id":247,"m":13,"q":"Why is the following 1NF table not in the 2NF?\nEmployees' Skills\nEmployee  Skill           Current Work Location\n--------  --------------  ---------------------\nJones     Typing          114 Main Street\nJones     Shorthand       114 Main Street\nJones     Whittling       114 Main Street\nBravo     Light Cleaning  73 Industrial Way\nEllis     Alchemy         73 Industrial Way\nEllis     Flying          73 Industrial Way\nHarrison  Light Cleaning  73 Industrial Way","o":["The non-prime attribute(s) are not dependent on each of the prime attributes.","The table contains multiple records for Same Employee name, so not in 2NF","The non-prime attribute(s) are dependent on each of the prime attributes.","The table is not in 1NF hence not in 2NF"],"c":0,"qv":"","ov":[],"ex":""},{"id":248,"m":13,"q":"Which of the 3NF conditions is not satisfied by the table below?\nTournament Winners\nTournament            Year  Winner          Winner Date of Birth\n--------------------  ----  --------------  --------------------\nDes Moines Masters    1998  Chip Masterson  14 March 1977\nIndiana Invitational  1998  Al Fredrickson  21 July 1975\nCleveland Open        1999  Bob Albertson   28 September 1968\nDes Moines Masters    1999  Al Fredrickson  21 July 1975\nIndiana Invitational  1999  Chip Masterson  14 March 1977","o":["Every prime attribute of a Table is non-transitively dependent on every candidate key of the table.","Every non-prime attribute of a Table is non-transitively dependent on every candidate key of the table.","The table must be in 2NF","The table must be in 1NF"],"c":1,"qv":"","ov":[],"ex":""},{"id":249,"m":13,"q":"Which statement about the Boyce-Codd Normal Form is not true?","o":["Only in rare cases does a 3NF table not meet the requirements of BCNF","BCNF was developed to address certain types of anomaly not dealt with by 3NF as originally defined.","Boyce-Codd normal form is a slightly stronger version of the third normal form.","A 3NF table which does not have multiple overlapping candidate keys is supposed to be not in BCNF."],"c":3,"qv":"","ov":[],"ex":""},{"id":250,"m":13,"q":"What is the full form of the DKNF?","o":["Donner-Korth Normal Form","Domain-Key Normal Form","Dual-Key Normal Form","Domain-Knowledge Normal Form"],"c":1,"qv":"","ov":[],"ex":""},{"id":251,"m":13,"q":"If a table is said to be in 3NF then which of the following may not be true?","o":["Every row-and-column intersection contains exactly one value from the applicable domain.","The table is free of modification anomalies.","Every non-prime attribute is non-transitively dependent (i.e. directly dependent) on every candidate key.","All its non-prime attributes are functionally dependent on the whole of every candidate key."],"c":1,"qv":"","ov":[],"ex":""},{"id":252,"m":13,"q":"Which of the following statements correctly describe the modification anomalies?","o":["Modification anomalies occur only up to Second Normal form","When modification anomalies exist, the table data cannot be modified","When an attempt is made to modify a table, undesired side-effects may follow","When modifying a table, errors frequently occur due to modification anomalies"],"c":2,"qv":"","ov":[],"ex":""},{"id":253,"m":2,"q":"Which of the following indicate that Y is transitively dependent on X?","o":["X->Y , Z->X","X->Y, Z->X","Y->Z, Z->X","Z->Y , X->Z"],"c":3,"qv":"","ov":[],"ex":""},{"id":254,"m":13,"q":"What is correct full form of the BCNF normal form?","o":["Boyce-Cartesian normal form","Boyce-Codd normal form","Bond-Codd normal form","Borne-Codd normal form"],"c":1,"qv":"","ov":[],"ex":""},{"id":255,"m":13,"q":"Which of the following is not a valid type of Modification anomaly?","o":["Update Anomaly","Insertion anomaly","Deletion anomaly","Drop anomaly"],"c":3,"qv":"","ov":[],"ex":""},{"id":256,"m":13,"q":"Considering the table structure and the data in the following table, which all modification anomalies can occur while modifying this table?\nFaculty ID  Faculty Name    Faculty Hire Date  Course Code\n----------  --------------  -----------------  -----------\n389         Dr. Giddens     10-Feb-1985        ENG-206\n407         Dr. Saperstein  19-Apr-1999        CMP-101\n407         Dr. Saperstein  19-Apr-1999        CMP-201","o":["Insertion, Update and Deletion anomaly","Only Insertion anomaly","Insertion and Update anomaly","Update and Deletion anomaly"],"c":0,"qv":"","ov":[],"ex":""},{"id":257,"m":13,"q":"Which of the following is not a valid objective of normalization?","o":["Get rid of the modification anomalies","Make the data model more informative to users","Completely avoid the need to change the table structure after normalization","Minimize redesign when extending the database structure"],"c":2,"qv":"","ov":[],"ex":""},{"id":258,"m":13,"q":"Consider following table structure, in which normal form is it?\nTransactions\nCustomer  Tr. ID  Date         Amount\n--------  ------  -----------  ------\nJones     12890   14-Oct-2003  −87\n          12904   15-Oct-2003  −50\nWilkins   12898   14-Oct-2003  −21\nStevens   12907   15-Oct-2003  −18\n          14920   20-Nov-2003  −70\n          15003   27-Nov-2003  −60","o":["3NF","1NF","2NF","Non 1NF"],"c":3,"qv":"","ov":[],"ex":""},{"id":259,"m":13,"q":"What is Functional dependency?","o":["In a given table, an attribute Y is said to have a functional dependency on a set of attributes X, if and only if each X value is associated with more than one Y value","In a given table, an attribute Y is said to have a functional dependency on a set of attributes X, if and only if each Y value is associated with precisely one X value","In a given table, an attribute Y is said to have a functional dependency on a set of attributes X, if and only if each X value is associated with precisely one Y value","In a given table, an attribute Y is said to have a functional dependency on a set of attributes X, if and only if each X value is associated with at least one Y value"],"c":2,"qv":"","ov":[],"ex":""},{"id":260,"m":2,"q":"What does X -> Y mean about the attributes X and Y?","o":["X is functionally dependent on Y","Y is functionally dependent on X","None of the above","X and Y are functionally dependent on each other"],"c":1,"qv":"","ov":[],"ex":""}];
